// Men's Social — Step 21: frosted-glass page change between Social, Man and Me. Includes Step 20 (simpler Discover, Fertility topic).
// Everything comes from his real activity on this phone.
// Run from the project folder:  node setup-step-21.mjs
import { mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("src/lib/liquid.ts")) {
  console.error("Run this inside the Men-s-Social-True folder, after Step 17.");
  process.exit(1);
}
for (const path of [".next", "setup-step-17.mjs", "setup-step-18.mjs", "setup-step-19.mjs", "setup-step-20.mjs"]) {
  if (existsSync(path)) { rmSync(path, { recursive: true, force: true }); console.log("  removed", path); }
}

const files = {
  "supabase/migrations/0003_fertility_topic.sql": "-- Men's Social — add \"Fertility and sperm health\" as its own topic for Content Studio content.\n-- Paste into Supabase → SQL Editor → New query → Run. Safe to run more than once.\n\nalter table public.content_items drop constraint if exists content_items_topic_check;\nalter table public.content_items\n  add constraint content_items_topic_check\n  check (topic in ('erection', 'ejaculation', 'libido', 'fertility', 'confidence', 'intimacy', 'wellbeing'));\n",
  "src/components/TabPager.tsx": "\"use client\";\n\n// The three main tabs side by side in one sliding strip, like a phone app.\n// - Swiping uses the phone's own scrolling (momentum + snap), so the page moves exactly with the finger\n//   and the next tab slides in beside it.\n// - All three tabs stay open in the background: no reloads, and each keeps its scroll position.\n// - The address (/social, /man, /me) follows the tab you land on.\n// - Other pages (an article, sign-up…) open on top of the strip and slide in from the right.\n\nimport { Component, useCallback, useEffect, useLayoutEffect, useRef, useState } from \"react\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport SocialTab from \"@/components/tabs/SocialTab\";\nimport ManTab from \"@/components/tabs/ManTab\";\nimport MeTab from \"@/components/tabs/MeTab\";\nimport { isTabRoot, stripPosition, TAB_PATHS, tabFor } from \"@/lib/tabs\";\nimport LockedTab from \"@/components/account/LockedTab\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nconst PANELS = [SocialTab, ManTab, MeTab];\n\n/** Tells the Liquid Glass tab bar where the strip is (0 = Social … 2 = Me). */\nconst setBubble = (position: number, byFinger = false) => {\n  stripPosition.set(Math.min(Math.max(position, 0), TAB_PATHS.length - 1), byFinger);\n  frostPanels(position);\n};\n\n/**\n * The same frosted-glass feel as Discover ⇄ Community, for the main tabs:\n * while the pages slide, the page leaving and the page arriving are seen through frosted glass\n * (blurred, a little faded and smaller), and each comes into focus as it reaches the centre.\n * It follows the strip, so it tracks the finger exactly and works for taps too.\n */\nconst reduceMotion = () => typeof window !== \"undefined\" && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\nfunction frostPanels(position: number) {\n  if (reduceMotion()) return;\n  for (let i = 0; i < TAB_PATHS.length; i++) {\n    const content = document.getElementById(`tab-panel-${i}`)?.firstElementChild as HTMLElement | null;\n    if (!content) continue;\n    const d = Math.min(Math.abs(position - i), 1); // 0 = in the centre, 1 = a full page away\n    if (d < 0.004 || d > 0.996) {\n      // In focus, or fully off screen: no effects at all (keeps scrolling smooth and saves battery)\n      content.style.filter = \"\";\n      content.style.opacity = \"\";\n      content.style.transform = \"\";\n      continue;\n    }\n    const e = Math.sin((d * Math.PI) / 2); // eases in quickly, like the Discover ⇄ Community glide\n    content.style.filter = `blur(${(e * 10).toFixed(2)}px) saturate(${(1 + e * 0.4).toFixed(3)})`;\n    content.style.opacity = String(1 - e * 0.45);\n    content.style.transform = `scale(${(1 - e * 0.03).toFixed(4)})`;\n  }\n}\n\nexport default function TabPager({ children }: { children: React.ReactNode }) {\n  const pathname = usePathname();\n  const router = useRouter();\n  const strip = useRef<HTMLDivElement>(null);\n  const onRoot = isTabRoot(pathname);\n  const tab = tabFor(pathname);\n  const [placed, setPlaced] = useState(false);\n  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const frame = useRef(0);\n  // Is a finger moving the pages (or did one just let go and the page is still gliding)?\n  const fingerUntil = useRef(0);\n  // Man and Me hold his private records: guests see a locked preview instead\n  const acc = useAccount();\n  const locked = acc.status === \"guest\";\n\n  // Put the strip on the right tab: instantly on first load, smoothly when a tab is tapped\n  useLayoutEffect(() => {\n    const el = strip.current;\n    if (!el || tab < 0) return;\n    const target = tab * el.clientWidth;\n    if (Math.abs(el.scrollLeft - target) > 1) {\n      el.scrollTo({ left: target, behavior: placed ? \"smooth\" : \"instant\" });\n    }\n    if (!placed) {\n      setBubble(tab);\n      setPlaced(true);\n    }\n  }, [tab, placed]);\n\n  // Inside an article etc., the bubble rests on that page's tab\n  useEffect(() => {\n    if (!onRoot && tab >= 0) setBubble(tab);\n  }, [onRoot, tab]);\n\n  // Turning the phone or resizing the window: stay on the same tab\n  useEffect(() => {\n    const onResize = () => {\n      const el = strip.current;\n      if (el && tab >= 0) el.scrollTo({ left: tab * el.clientWidth, behavior: \"instant\" });\n    };\n    window.addEventListener(\"resize\", onResize);\n    return () => window.removeEventListener(\"resize\", onResize);\n  }, [tab]);\n\n  const onScroll = useCallback(() => {\n    const el = strip.current;\n    if (!el) return;\n    cancelAnimationFrame(frame.current);\n    frame.current = requestAnimationFrame(() =>\n      setBubble(el.scrollLeft / el.clientWidth, performance.now() < fingerUntil.current),\n    );\n    // When the strip comes to rest on another tab, update the address (without adding to Back history)\n    if (settleTimer.current) clearTimeout(settleTimer.current);\n    settleTimer.current = setTimeout(() => {\n      const landed = Math.round(el.scrollLeft / el.clientWidth);\n      if (isTabRoot(window.location.pathname) && TAB_PATHS[landed] !== window.location.pathname) {\n        router.replace(TAB_PATHS[landed], { scroll: false });\n      }\n    }, 90);\n  }, [router]);\n\n  return (\n    <>\n      <div\n        ref={strip}\n        onScroll={onScroll}\n        onTouchStart={() => (fingerUntil.current = Infinity)}\n        onTouchEnd={() => (fingerUntil.current = performance.now() + 700)}\n        onTouchCancel={() => (fingerUntil.current = performance.now() + 700)}\n        className={`tab-strip ${placed ? \"opacity-100\" : \"opacity-0\"}`}\n        inert={!onRoot}\n        aria-hidden={!onRoot}\n      >\n        {PANELS.map((Panel, i) => (\n          <section\n            key={TAB_PATHS[i]}\n            id={`tab-panel-${i}`}\n            className=\"tab-panel\"\n            aria-label={[\"Social\", \"Man\", \"Me\"][i]}\n            aria-hidden={onRoot && i !== tab ? true : undefined}\n          >\n            <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">\n              <PanelBoundary>\n                {i > 0 && acc.status === \"loading\" ? (\n                  <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n                ) : i > 0 && locked ? (\n                  <LockedTab tab={i === 1 ? \"man\" : \"me\"} />\n                ) : (\n                  <Panel />\n                )}\n              </PanelBoundary>\n            </div>\n          </section>\n        ))}\n      </div>\n\n      {!onRoot && (\n        <div className=\"overlay-page\" id=\"overlay-page\">\n          <div className=\"mx-auto max-w-md px-5 pb-32 pt-6\">{children}</div>\n        </div>\n      )}\n    </>\n  );\n}\n\n/** If one tab crashes, the other two keep working. */\nclass PanelBoundary extends Component<{ children: React.ReactNode }, { failed: boolean }> {\n  state = { failed: false };\n  static getDerivedStateFromError() {\n    return { failed: true };\n  }\n  render() {\n    if (!this.state.failed) return this.props.children;\n    return (\n      <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n        <p className=\"font-semibold\">Something went wrong here</p>\n        <button onClick={() => location.reload()} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n          Reload\n        </button>\n      </div>\n    );\n  }\n}\n",
  "src/components/social/ContentCards.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ChevronRight } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\nexport const contentHref = (id: string) => `/social/c/${id}`;\n\n/** Small card for horizontal rows on Discover. */\nexport function ContentCard({ item, className = \"w-44 shrink-0 snap-start\" }: { item: ContentItem; className?: string }) {\n  return (\n    <Link\n      href={contentHref(item.id)}\n      className={`block overflow-hidden rounded-3xl bg-surface ring-1 ring-line transition-transform active:scale-[0.98] ${className}`}\n    >\n      <Cover item={item} className=\"h-24 w-full\" />\n      <div className=\"p-3\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"mt-1 line-clamp-3 text-[13px] font-semibold leading-snug\">{item.title}</p>\n      </div>\n    </Link>\n  );\n}\n\n/** Row for lists: search results, saved, topic pages. With `reason`, it also says why it's suggested. */\nexport function ContentRow({ item, reason }: { item: ContentItem; reason?: string }) {\n  return (\n    <Link href={contentHref(item.id)} className=\"flex items-center gap-3 rounded-3xl bg-surface p-3 ring-1 ring-line\">\n      <Cover item={item} className=\"h-16 w-16 shrink-0 rounded-2xl\" showPlay={false} />\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"line-clamp-2 text-sm font-semibold leading-snug\">{item.title}</p>\n        {reason && <p className=\"mt-0.5 truncate text-[11px] text-ink-soft\">{reason}</p>}\n      </div>\n      <BookmarkButton contentId={item.id} variant=\"plain\" />\n    </Link>\n  );\n}\n\n/** A Discover section: title, \"See all\", and a horizontal row of cards. */\nexport function SectionRow({\n  id,\n  title,\n  blurb,\n  items,\n}: {\n  id: string;\n  title: string;\n  blurb?: string;\n  items: ContentItem[];\n}) {\n  if (items.length === 0) return null;\n  return (\n    <section aria-labelledby={`sec-${id}`}>\n      <div className=\"flex items-end justify-between gap-3\">\n        <div>\n          <h2 id={`sec-${id}`} className=\"text-base font-bold\">\n            {title}\n          </h2>\n          {blurb && <p className=\"text-xs text-ink-soft\">{blurb}</p>}\n        </div>\n        <Link href={`/social/topic/${id}`} className=\"flex shrink-0 items-center text-xs font-semibold text-forest\">\n          See all <ChevronRight size={14} />\n        </Link>\n      </div>\n      <div className=\"mt-3 flex snap-x gap-3 overflow-x-auto rounded-3xl pb-1 [scrollbar-width:none]\">\n        {items.map((c) => (\n          <ContentCard key={c.id} item={c} />\n        ))}\n      </div>\n    </section>\n  );\n}\n",
  "src/components/social/ContentDetail.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Check, ExternalLink, MessageCircle, PlayCircle, ShieldCheck } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { ContentRow } from \"./ContentCards\";\nimport { DoctorCheck, PelvicFloorTrainer, QuizRunner } from \"./ContentTools\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { useLang, type Lang } from \"@/lib/me/lang\";\nimport { getContent, KIND_LABEL } from \"@/lib/content/select\";\nimport { feedStore, useFeed } from \"@/lib/feed/store\";\nimport { socialStore } from \"@/lib/social/store\";\n\n/** Full page for any piece of content: guide, article, video, quiz, tool or expert answer. */\nexport default function ContentDetail({ id, back }: { id: string; back: { href: string; label: string } }) {\n  const library = useLibrary();\n  const item = getContent(id, library.items);\n  const feed = useFeed();\n  const showToast = useToast();\n  // Opens in the language he chose (Me tab); he can still switch on the page\n  const appLang = useLang();\n  const [picked, setLang] = useState<Lang | null>(null);\n  const lang = picked ?? appLang;\n  // Remember he opened it, so Discover can suggest things he hasn't read yet\n  const found = Boolean(item);\n  useEffect(() => {\n    if (found) socialStore.recordOpen(id);\n  }, [found, id]);\n\n  if (!item && !library.ready) {\n    return (\n      <div className=\"space-y-4\" aria-busy=\"true\" aria-label=\"Loading\">\n        <div className=\"aspect-[16/9] animate-pulse rounded-[28px] bg-forest-deep/15\" />\n        <div className=\"h-7 w-3/4 animate-pulse rounded-full bg-line\" />\n        <div className=\"h-40 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  if (!item) {\n    return (\n      <div className=\"space-y-4\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {back.label}\n        </Link>\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">This content isn&apos;t available</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">It may have been moved or removed.</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Go to Discover\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  const topic = TOPICS.find((t) => t.id === item.topic);\n  const sw = lang === \"sw\" && Boolean(item.bodySw);\n  const title = sw && item.titleSw ? item.titleSw : item.title;\n  const body = sw ? item.bodySw : item.body;\n  const read = Boolean(feed.lessons[item.id]);\n  const related = library.items.filter((c) => c.topic === item.topic && c.id !== item.id)\n    .sort((a, b) => b.priority - a.priority)\n    .slice(0, 3);\n\n  return (\n    <article className=\"stagger space-y-5\">\n      <div className=\"flex items-center justify-between\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {back.label}\n        </Link>\n        <BookmarkButton contentId={item.id} />\n      </div>\n\n      <div className=\"overflow-hidden rounded-[28px]\">\n        {item.kind === \"video\" ? (\n          <div className=\"relative\">\n            <Cover item={item} className=\"aspect-video w-full\" showPlay={false} />\n            <div className=\"absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/30 text-white\">\n              <PlayCircle size={44} />\n              <p className=\"text-sm font-semibold\">Video coming soon</p>\n              <p className=\"text-xs text-white/80\">Key points are below</p>\n            </div>\n          </div>\n        ) : (\n          <Cover item={item} className=\"aspect-[16/9] w-full\" />\n        )}\n      </div>\n\n      <header>\n        <p className=\"text-[11px] font-semibold uppercase tracking-wider text-forest\">\n          <Link href={`/social/topic/${item.topic}`} className=\"underline-offset-2 hover:underline\">\n            {topic?.title}\n          </Link>{\" \"}\n          · {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <h1 className=\"mt-2 text-[26px] font-bold leading-tight\">{title}</h1>\n        {!sw && <p className=\"mt-2 text-[15px] leading-relaxed text-ink-soft\">{item.summary}</p>}\n        <p className=\"mt-3 flex items-start gap-1.5 rounded-2xl bg-bg px-3 py-2 text-[11px] leading-snug text-ink-soft ring-1 ring-line\">\n          <ShieldCheck size={13} className=\"mt-px shrink-0 text-forest\" />\n          <span>\n            {item.source}\n            {item.fixture && \" · Sample content for development\"}\n          </span>\n        </p>\n        {(item.bodySw || item.origin) && (\n          <div className=\"mt-3 flex items-center justify-between gap-2\">\n            {item.bodySw ? (\n              <div className=\"inline-flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\" role=\"tablist\" aria-label=\"Language\">\n                {([\"en\", \"sw\"] as const).map((l) => (\n                  <button\n                    key={l}\n                    role=\"tab\"\n                    aria-selected={lang === l}\n                    onClick={() => setLang(l)}\n                    className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n                  >\n                    {l === \"en\" ? \"English\" : \"Kiswahili\"}\n                  </button>\n                ))}\n              </div>\n            ) : (\n              <span />\n            )}\n            {item.origin && (\n              <a\n                href={item.origin.url}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"flex items-center gap-1 text-xs font-semibold text-forest\"\n              >\n                {item.origin.format === \"reel\" ? \"Watch on Instagram\" : \"View on Instagram\"} <ExternalLink size={12} />\n              </a>\n            )}\n          </div>\n        )}\n      </header>\n\n      {item.kind === \"expert\" && item.question && (\n        <blockquote className=\"flex gap-3 rounded-3xl bg-mint/60 p-4\">\n          <MessageCircle size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <p className=\"text-sm font-medium italic text-forest-deep\">&ldquo;{item.question}&rdquo;</p>\n        </blockquote>\n      )}\n\n      {body && (\n        <div lang={sw ? \"sw\" : \"en\"} className=\"space-y-3 rounded-3xl bg-surface p-5 text-[15px] leading-relaxed ring-1 ring-line\">\n          {body.map((p, i) =>\n            p.startsWith(\"## \") ? (\n              <h2 key={i} className=\"pt-2 text-lg font-bold\">\n                {p.slice(3)}\n              </h2>\n            ) : (\n              <p key={i}>{p}</p>\n            ),\n          )}\n        </div>\n      )}\n\n      {item.keyPoints && (\n        <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n          <h2 className=\"font-bold\">Key points</h2>\n          <ol className=\"mt-3 space-y-2\">\n            {item.keyPoints.map((k, i) => (\n              <li key={i} className=\"flex gap-3 text-sm\">\n                <span className=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-mint text-xs font-bold text-forest\">\n                  {i + 1}\n                </span>\n                {k}\n              </li>\n            ))}\n          </ol>\n        </div>\n      )}\n\n      {item.quiz && <QuizRunner questions={item.quiz} />}\n      {item.tool === \"pelvic-floor\" && <PelvicFloorTrainer />}\n      {item.tool === \"doctor-check\" && <DoctorCheck />}\n\n      {item.inManFeed && feed.ready && (\n        <button\n          onClick={() => {\n            if (read) return;\n            feedStore.markLessonRead(item.id);\n            showToast(`Lesson read · +${item.points ?? 10} points`);\n          }}\n          className={`flex w-full items-center justify-center gap-2 rounded-full py-3.5 text-sm font-semibold transition-transform active:scale-[0.98] ${\n            read ? \"bg-mint text-forest\" : \"bg-forest text-white\"\n          }`}\n        >\n          {read ? (\n            <>\n              <Check size={16} /> You&apos;ve read this\n            </>\n          ) : (\n            `Mark as read · +${item.points ?? 10} points`\n          )}\n        </button>\n      )}\n\n      <p className=\"px-2 text-center text-[11px] text-ink-soft\">General education, not medical advice.</p>\n\n      {related.length > 0 && (\n        <section className=\"space-y-3 pt-2\">\n          <h2 className=\"text-base font-bold\">More on {topic?.title.toLowerCase()}</h2>\n          {related.map((r) => (\n            <ContentRow key={r.id} item={r} />\n          ))}\n        </section>\n      )}\n    </article>\n  );\n}\n",
  "src/components/social/Discover.tsx": "\"use client\";\n\n// Discover home — \"show less, deliver more\".\n// 1. One featured insight (rotates daily, prefers what he hasn't read)\n// 2. For you: 2–3 picks, each saying why it's suggested\n// 3. Quick learning: one or two short videos\n// 4. One question men often ask (with a way into Community)\n// 5. Explore all topics: the full library, one tap away\n// Everything else lives on the topic pages, so nothing is lost.\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowRight, ChevronRight, MessageCircle, SlidersHorizontal } from \"lucide-react\";\nimport FeaturedCard from \"./FeaturedCard\";\nimport { ContentCard, ContentRow, contentHref } from \"./ContentCards\";\nimport InterestsSheet from \"./InterestsSheet\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport { featuredToday, questionToday, quickVideos, recommendations, topicTiles } from \"@/lib/content/select\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { useSocial } from \"@/lib/social/store\";\n\nexport function DiscoverSkeleton() {\n  return (\n    <div className=\"space-y-4\" aria-busy=\"true\" aria-label=\"Loading\">\n      <div className=\"h-[340px] animate-pulse rounded-[28px] bg-forest-deep/15\" />\n      <div className=\"h-5 w-40 animate-pulse rounded-full bg-line\" />\n      <div className=\"h-24 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n    </div>\n  );\n}\n\nexport default function Discover() {\n  const { interests, bookmarks, history, ready } = useSocial();\n  const [pickTopics, setPickTopics] = useState(false);\n  const { items } = useLibrary();\n\n  if (!ready) return <DiscoverSkeleton />;\n\n  const me = { interests, bookmarks, history };\n  const featured = featuredToday(me, items);\n  if (!featured) {\n    return (\n      <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n        <p className=\"font-semibold\">No content yet</p>\n        <p className=\"mt-1 text-sm text-ink-soft\">New guides and answers will appear here soon.</p>\n      </div>\n    );\n  }\n\n  const followed = TOPICS.filter((t) => interests.includes(t.id) && t.id === featured.topic);\n  const reason = followed.length\n    ? `Picked for you because you follow ${followed[0].short}.`\n    : \"Picked by our editors as today's most useful read.\";\n  const picks = recommendations(me, items, [featured.id]);\n  const videos = quickVideos(me, items);\n  const question = questionToday(me, items);\n  const tiles = topicTiles(items);\n  const answerIntro = question?.body?.find((p) => !p.startsWith(\"## \"));\n\n  return (\n    <div className=\"stagger space-y-7\">\n      <FeaturedCard item={featured} reason={reason} />\n\n      {/* For you */}\n      <section aria-labelledby=\"sec-for-you\" className=\"space-y-3\">\n        <div className=\"flex items-end justify-between\">\n          <div>\n            <h2 id=\"sec-for-you\" className=\"text-base font-bold\">For you</h2>\n            <p className=\"text-xs text-ink-soft\">\n              {interests.length ? TOPICS.filter((t) => interests.includes(t.id)).map((t) => t.short).join(\" · \") : \"Choose topics to make this yours\"}\n            </p>\n          </div>\n          <button onClick={() => setPickTopics(true)} className=\"flex items-center gap-1 text-xs font-semibold text-forest\">\n            <SlidersHorizontal size={14} /> {interests.length ? \"Edit\" : \"Choose topics\"}\n          </button>\n        </div>\n        <div className=\"space-y-2.5\">\n          {picks.map(({ item, reason }) => (\n            <ContentRow key={item.id} item={item} reason={reason} />\n          ))}\n        </div>\n      </section>\n\n      {/* Quick learning */}\n      {videos.length > 0 && (\n        <section aria-labelledby=\"sec-videos\" className=\"space-y-3\">\n          <div className=\"flex items-end justify-between\">\n            <div>\n              <h2 id=\"sec-videos\" className=\"text-base font-bold\">Quick learning</h2>\n              <p className=\"text-xs text-ink-soft\">Two minutes or less</p>\n            </div>\n            <Link href=\"/social/topic/videos\" className=\"flex items-center text-xs font-semibold text-forest\">\n              All videos <ChevronRight size={14} />\n            </Link>\n          </div>\n          <div className=\"grid grid-cols-2 gap-3\">\n            {videos.map((v) => (\n              <ContentCard key={v.id} item={v} className=\"w-full\" />\n            ))}\n          </div>\n        </section>\n      )}\n\n      {/* One important question */}\n      {question && (\n        <section aria-labelledby=\"sec-question\" className=\"rounded-3xl bg-mint/60 p-5\">\n          <p id=\"sec-question\" className=\"flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-forest\">\n            <MessageCircle size={13} /> A question men often ask\n          </p>\n          <p className=\"mt-2 text-lg font-bold leading-snug text-forest-deep\">&ldquo;{question.question}&rdquo;</p>\n          {answerIntro && <p className=\"mt-2 line-clamp-3 text-sm text-ink-soft\">{answerIntro}</p>}\n          <div className=\"mt-4 flex flex-wrap items-center gap-2\">\n            <Link href={contentHref(question.id)} className=\"flex items-center gap-1.5 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white\">\n              Read the answer <ArrowRight size={14} />\n            </Link>\n            <Link href=\"/social?tab=community\" className=\"rounded-full px-4 py-2.5 text-sm font-semibold text-forest ring-1 ring-line\">\n              Ask your own question\n            </Link>\n          </div>\n        </section>\n      )}\n\n      {/* Explore all topics */}\n      <section aria-labelledby=\"sec-topics\" className=\"space-y-3\">\n        <div>\n          <h2 id=\"sec-topics\" className=\"text-base font-bold\">Explore all topics</h2>\n          <p className=\"text-xs text-ink-soft\">Every guide, answer, video and tool</p>\n        </div>\n        <div className=\"grid grid-cols-2 gap-2.5\">\n          {tiles.map((t) => (\n            <Link\n              key={t.id}\n              href={`/social/topic/${t.id}`}\n              className={`flex min-h-[72px] flex-col justify-between rounded-2xl bg-surface p-3.5 ring-1 ring-line transition-transform active:scale-[0.98] ${\n                interests.includes(t.id as never) ? \"ring-forest\" : \"\"\n              }`}\n            >\n              <span className=\"text-sm font-semibold leading-snug\">{t.title}</span>\n              <span className=\"mt-1 text-[11px] text-ink-soft\">\n                {t.count} {t.count === 1 ? \"item\" : \"items\"}\n              </span>\n            </Link>\n          ))}\n        </div>\n      </section>\n\n      <p className=\"px-2 text-center text-[11px] leading-relaxed text-ink-soft\">\n        All content here is general education, not medical advice. Items marked &quot;Sample&quot; are drafts that will be\n        reviewed by a qualified health professional before launch.\n      </p>\n\n      <InterestsSheet open={pickTopics} onClose={() => setPickTopics(false)} current={interests} />\n    </div>\n  );\n}\n",
  "src/lib/account/merge.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { mergeFeed, mergeProgress, mergeSocial, normalizeTzPhone } from \"./merge\";\nimport type { TrackingRecord } from \"../progress/types\";\nimport type { SocialDB } from \"../social/store\";\n\nconst rec = (id: string, value: number, updatedAt: string): TrackingRecord => ({\n  id, userId: \"local\", metric: \"water\", value, unit: \"ml\", source: \"manual\",\n  recordedAt: \"2026-10-13T08:00:00Z\", localDate: \"2026-10-13\", createdAt: \"2026-10-13T08:00:00Z\", updatedAt,\n});\nconst emptySocial: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {}, history: {} };\n\ndescribe(\"merging phone data with his account\", () => {\n  it(\"keeps records from both sides and the newest edit of the same record\", () => {\n    const local = { records: [rec(\"a\", 250, \"2026-10-13T09:00:00Z\"), rec(\"b\", 500, \"2026-10-13T09:00:00Z\")], goals: [] };\n    const remote = { records: [rec(\"a\", 300, \"2026-10-13T10:00:00Z\"), rec(\"c\", 750, \"2026-10-12T09:00:00Z\")], goals: [] };\n    const m = mergeProgress(local, remote, \"user-1\");\n    expect(m.records.map((r) => [r.id, r.value]).sort()).toEqual([[\"a\", 300], [\"b\", 500], [\"c\", 750]]);\n    expect(m.records.every((r) => r.userId === \"user-1\")).toBe(true);\n  });\n  it(\"keeps the goal he changed most recently, and his account's goal over a default\", () => {\n    const def = { metric: \"water\" as const, target: 2500, unit: \"ml\" as const, period: \"day\" as const, direction: \"increase\" as const, updatedAt: \"\" };\n    const set = { ...def, target: 3000, updatedAt: \"2026-10-10T00:00:00Z\" };\n    expect(mergeProgress({ records: [], goals: [def] }, { goals: [set] }).goals[0].target).toBe(3000);\n  });\n  it(\"works when the account is empty (first sign-in)\", () => {\n    const local = { records: [rec(\"a\", 250, \"x\")], goals: [] };\n    expect(mergeProgress(local, null).records).toHaveLength(1);\n  });\n  it(\"merges daily choices and lessons from both phones\", () => {\n    const local = { days: { \"2026-10-13\": { walk: { status: \"done\" as const, at: \"2026-10-13T10:00:00Z\" } } }, lessons: { l1: { localDate: \"2026-10-13\", at: \"2026-10-13T10:00:00Z\" } }, settings: { discreet: false } };\n    const remote = { days: { \"2026-10-13\": { walk: { status: \"later\" as const, at: \"2026-10-13T08:00:00Z\" }, meal: { status: \"done\" as const, at: \"2026-10-13T08:00:00Z\" } } }, lessons: { l1: { localDate: \"2026-10-12\", at: \"2026-10-12T10:00:00Z\" } }, settings: { discreet: true } };\n    const m = mergeFeed(local, remote);\n    expect(m.days[\"2026-10-13\"].walk.status).toBe(\"done\");\n    expect(m.days[\"2026-10-13\"].meal.status).toBe(\"done\");\n    expect(m.lessons.l1.localDate).toBe(\"2026-10-12\");\n    expect(m.settings.discreet).toBe(true);\n  });\n  it(\"merges bookmarks, topics and reactions, keeping his name from this phone\", () => {\n    const local = { ...emptySocial, bookmarks: { a: \"1\" }, interests: [\"libido\" as const], nickname: \"Juma\", reactions: { p1: [\"helpful\" as never] } };\n    const remote = { ...emptySocial, bookmarks: { b: \"2\" }, interests: [\"libido\" as const, \"confidence\" as const], nickname: \"J\", reactions: { p1: [\"support\" as never] } };\n    const m = mergeSocial(local, remote);\n    expect(Object.keys(m.bookmarks).sort()).toEqual([\"a\", \"b\"]);\n    expect(m.interests).toEqual([\"libido\", \"confidence\"]);\n    expect(m.nickname).toBe(\"Juma\");\n    expect(m.reactions.p1.sort()).toEqual([\"helpful\", \"support\"]);\n    expect(mergeSocial({ ...emptySocial }, remote).nickname).toBe(\"J\");\n  });\n});\n\ndescribe(\"Tanzanian phone numbers\", () => {\n  it(\"accepts the usual ways people write them\", () => {\n    for (const p of [\"0712 345 678\", \"+255712345678\", \"255 712 345 678\", \"712345678\", \"0654-123-456\"]) {\n      expect(normalizeTzPhone(p), p).toMatch(/^\\+255[67]\\d{8}$/);\n    }\n    expect(normalizeTzPhone(\"0712 345 678\")).toBe(\"+255712345678\");\n  });\n  it(\"rejects numbers that aren't Tanzanian mobiles\", () => {\n    for (const p of [\"12345\", \"0812345678\", \"+254712345678\", \"07123456789\"]) expect(normalizeTzPhone(p), p).toBeNull();\n  });\n});\n",
  "src/lib/account/merge.ts": "// Combines what's on this phone with what's saved in his account, without losing either.\n// Used when he signs in (e.g. guest progress + an account he made on another phone).\n// Pure functions — easy to test.\n\nimport type { FeedDB } from \"../feed/store\";\nimport type { SocialDB } from \"../social/store\";\nimport type { Goal, TrackingRecord } from \"../progress/types\";\n\nexport type ProgressDB = { records: TrackingRecord[]; goals: Goal[] };\n\n/** Keep one of each id; if both sides have it, keep the most recently changed. */\nfunction byIdNewest<T extends { id: string }>(a: T[], b: T[], stamp: (x: T) => string): T[] {\n  const map = new Map<string, T>();\n  for (const x of [...a, ...b]) {\n    const have = map.get(x.id);\n    if (!have || stamp(x) > stamp(have)) map.set(x.id, x);\n  }\n  return [...map.values()];\n}\n\nexport function mergeProgress(local: ProgressDB, remote: Partial<ProgressDB> | null, userId?: string): ProgressDB {\n  const r = { records: remote?.records ?? [], goals: remote?.goals ?? [] };\n  const records = byIdNewest(local.records, r.records, (x) => x.updatedAt ?? \"\")\n    .map((x) => (userId ? { ...x, userId } : x))\n    .sort((a, b) => a.recordedAt.localeCompare(b.recordedAt));\n  const goals = new Map<string, Goal>();\n  for (const g of [...local.goals, ...r.goals]) {\n    const have = goals.get(g.metric);\n    if (!have || (g.updatedAt ?? \"\") > (have.updatedAt ?? \"\")) goals.set(g.metric, g);\n  }\n  return { records, goals: [...goals.values()] };\n}\n\nexport function mergeFeed(local: FeedDB, remote: Partial<FeedDB> | null): FeedDB {\n  const days: FeedDB[\"days\"] = {};\n  for (const src of [local.days, remote?.days ?? {}]) {\n    for (const [day, choices] of Object.entries(src)) {\n      days[day] = { ...days[day] };\n      for (const [id, c] of Object.entries(choices)) {\n        const have = days[day][id];\n        if (!have || c.at > have.at) days[day][id] = c;\n      }\n    }\n  }\n  const lessons: FeedDB[\"lessons\"] = { ...(remote?.lessons ?? {}) };\n  for (const [id, l] of Object.entries(local.lessons)) {\n    if (!lessons[id] || l.at < lessons[id].at) lessons[id] = l; // first time he read it\n  }\n  return {\n    days,\n    lessons,\n    settings: { discreet: Boolean(local.settings.discreet || remote?.settings?.discreet) },\n  };\n}\n\nexport function mergeSocial(local: SocialDB, remote: Partial<SocialDB> | null): SocialDB {\n  const r: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {}, history: {}, ...remote };\n  const reactions: SocialDB[\"reactions\"] = { ...r.reactions };\n  for (const [id, kinds] of Object.entries(local.reactions)) reactions[id] = [...new Set([...(reactions[id] ?? []), ...kinds])];\n  return {\n    bookmarks: { ...r.bookmarks, ...local.bookmarks },\n    interests: [...new Set([...r.interests, ...local.interests])],\n    nickname: local.nickname || r.nickname,\n    posts: byIdNewest(r.posts, local.posts, (p) => p.createdAt),\n    replies: byIdNewest(r.replies, local.replies, (p) => p.createdAt),\n    reactions,\n    reports: { ...r.reports, ...local.reports },\n    history: { ...r.history, ...local.history },\n  };\n}\n\n/** Tanzanian phone numbers in any common format → +255XXXXXXXXX, or null if it isn't one. */\nexport function normalizeTzPhone(input: string): string | null {\n  const digits = input.replace(/[^\\d+]/g, \"\");\n  const m = /^(?:\\+?255|0)?([67]\\d{8})$/.exec(digits);\n  return m ? `+255${m[1]}` : null;\n}\n",
  "src/lib/content/instagram.ts": "// Content adapted from the Kayani Herbs Instagram page (account \"Mimea Tiba\").\n// Rules applied to every post before it goes in the app:\n// - Keep the useful education; remove product promotion, prices, phone numbers and testimonials\n// - Remove cure claims (\"unatibu kabisa\", \"huponya\") and anything not supported by evidence\n// - Add when to see a doctor\n// - Marked draft until reviewed by a qualified health professional\n\nimport type { ContentItem } from \"./types\";\n\nconst IG_SOURCE = \"Adapted from Kayani Herbs on Instagram · Draft, pending review by a qualified health professional\";\n\nexport const INSTAGRAM_CONTENT: ContentItem[] = [\n  {\n    id: \"ig-eating-day-calm-stomach\",\n    kind: \"guide\",\n    topic: \"wellbeing\",\n    title: \"A simple eating day for a calmer stomach\",\n    titleSw: \"Ratiba rahisi ya kula kwa tumbo lililotulia\",\n    summary: \"Rumbling, gas and feeling full all day? Start with what you eat and when. A practical day plan using everyday Tanzanian food.\",\n    minutes: 4,\n    priority: 82,\n    tags: [\"digestion\", \"gas\", \"bloating\", \"constipation\", \"meal plan\", \"tumbo\", \"chakula\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/reel/DeMpLfKCb4B/\", postedAt: \"2026-10-07\", format: \"reel\" },\n    cover: { tone: \"sand\", motif: \"grid\" },\n    body: [\n      \"A stomach that rumbles, fills with gas, or doesn't empty properly can leave you tired and uncomfortable all day. Before looking for medicine, start with what goes into your stomach every day.\",\n      \"## Morning (6–7 am)\",\n      \"Drink water first, before tea full of sugar and mandazi. Then eat: 1–2 eggs, avocado, papaya or another fruit, and uji of millet or sorghum. Eat slowly and chew well — the aim is not to stuff yourself.\",\n      \"## Mid-morning (10–11 am), if hungry\",\n      \"Skip chips, soda and biscuits. Have one fruit, such as papaya, an orange or a ripe banana, and keep sipping water.\",\n      \"## Lunch (12–2 pm)\",\n      \"Build your plate: half vegetables, a quarter protein (fish, chicken, eggs or beans if they suit you), and a quarter rice, ugali, potatoes or plantain. Eat until you're comfortably full — not until you can't walk. Afterwards, don't lie down: walk for 10–15 minutes.\",\n      \"## Late afternoon (4–5 pm)\",\n      \"If you're hungry, keep it light: fruit, avocado, a few groundnuts, or low-sugar yoghurt if your stomach handles it.\",\n      \"## Evening (7–8 pm)\",\n      \"Let your stomach rest. Fish, chicken or eggs with vegetables, or a small portion of ugali or potatoes with vegetables and protein. Try to leave 2–3 hours before you sleep.\",\n      \"## Cut down on\",\n      \"Lots of soda, alcohol, chips and deep-fried food, too much sugar, fast food, very big meals, eating fast, and heavy food late at night.\",\n      \"## Every body is different\",\n      \"Don't blame yourself if a food like beans, milk or onions gives you gas. Notice which foods affect you and adjust.\",\n      \"## When to see a doctor\",\n      \"See a doctor if you have blood in your stool, black stools, weight loss without trying, vomiting, strong pain that doesn't go away, or if these problems last more than a few weeks.\",\n    ],\n    bodySw: [\n      \"Tumbo linalounguruma, kujaa gesi au choo kutotoka vizuri kunaweza kukufanya uchoke na usijisikie vizuri siku nzima. Kabla ya kutafuta dawa, anza na kile unachokiingiza tumboni kila siku.\",\n      \"## Asubuhi (saa 12–1)\",\n      \"Kunywa maji kwanza, kabla ya chai yenye sukari nyingi na maandazi. Kisha kula: mayai 1–2, parachichi, papai au tunda lingine, na uji wa ulezi au mtama. Kula taratibu na tafuna vizuri — lengo si kushiba kupita kiasi.\",\n      \"## Saa 4–5 asubuhi, kama una njaa\",\n      \"Usikimbilie chipsi, soda au biskuti. Chukua tunda moja, kama papai, chungwa au ndizi mbivu, na endelea kunywa maji kidogo kidogo.\",\n      \"## Mchana (saa 6–8)\",\n      \"Panga sahani yako: nusu mboga, robo protini (samaki, kuku, mayai au maharage kama yanakufaa), na robo wali, ugali, viazi au ndizi. Kula mpaka ushibe vizuri — si mpaka ushindwe kutembea. Baada ya kula usilale: tembea dakika 10–15.\",\n      \"## Jioni (saa 10–11)\",\n      \"Kama una njaa, kula kitu chepesi: tunda, parachichi, karanga kiasi, au mtindi usio na sukari nyingi kama tumbo lako linauvumilia.\",\n      \"## Usiku (saa 1–2)\",\n      \"Acha tumbo lipumzike. Samaki, kuku au mayai pamoja na mboga, au ugali/viazi kidogo pamoja na mboga na protini. Jaribu kuacha masaa 2–3 kabla ya kulala.\",\n      \"## Punguza\",\n      \"Soda nyingi, pombe, chipsi na vyakula vya kukaanga sana, sukari nyingi, fast food, milo mikubwa sana, kula kwa haraka, na chakula kizito usiku.\",\n      \"## Kila mwili ni tofauti\",\n      \"Usijilaumu kama chakula fulani kama maharage, maziwa au vitunguu kinakupa gesi. Angalia vyakula vinavyokuathiri na ubadilishe.\",\n      \"## Wakati wa kumwona daktari\",\n      \"Mwone daktari ukiona damu kwenye choo, choo cheusi, kupungua uzito bila sababu, kutapika, maumivu makali yasiyoisha, au kama tatizo linaendelea zaidi ya wiki chache.\",\n    ],\n  },\n  {\n    id: \"ig-strength-starts-daily\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Sexual strength starts with your daily health\",\n    titleSw: \"Nguvu za kiume zinaanzia kwenye afya yako ya kila siku\",\n    summary: \"Low desire, weak erections or tiring quickly often start outside the bedroom. Here's where to begin.\",\n    minutes: 2,\n    priority: 78,\n    tags: [\"nguvu za kiume\", \"erection\", \"desire\", \"lifestyle\", \"stamina\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdyoemfghfF/\", postedAt: \"2026-09-27\", format: \"carousel\" },\n    cover: { tone: \"forest\", motif: \"arc\" },\n    body: [\n      \"Sexual strength doesn't start in the bedroom — it starts with how you live every day.\",\n      \"If desire has dropped, erections are weaker, or you tire quickly, begin with the basics: eat well, drink enough water, move your body, sleep enough, and cut down on alcohol and heavily processed food.\",\n      \"Don't ignore other health problems that may be going on. Blood pressure, blood sugar, stress and stomach problems can all affect how you feel.\",\n      \"If things don't improve after a few weeks of better habits, or if problems started suddenly, see a doctor. It's common, and doctors deal with it every day.\",\n      \"Good health begins with the small things you do each day.\",\n    ],\n    bodySw: [\n      \"Nguvu za kiume hazianzi chumbani — zinaanzia kwenye jinsi unavyoishi kila siku.\",\n      \"Kama hamu ya tendo imepungua, uume unasimama legelege au unachoka haraka, anza na misingi: kula vizuri, kunywa maji ya kutosha, fanya mazoezi, pata usingizi wa kutosha, na punguza pombe na vyakula vilivyosindikwa sana.\",\n      \"Usipuuze changamoto nyingine za kiafya zinazoendelea. Presha, sukari, msongo wa mawazo na matatizo ya tumbo vinaweza kuathiri jinsi unavyojisikia.\",\n      \"Kama hali haibadiliki baada ya wiki kadhaa za kuboresha tabia hizi, au kama tatizo lilianza ghafla, mwone daktari. Ni jambo la kawaida, na madaktari wanalishughulikia kila siku.\",\n      \"Afya nzuri huanzia kwenye mambo madogo unayofanya kila siku.\",\n    ],\n  },\n  {\n    id: \"ig-second-round\",\n    kind: \"guide\",\n    topic: \"ejaculation\",\n    title: \"Going again: the time between rounds\",\n    titleSw: \"Kurudia tendo: muda kati ya raundi\",\n    summary: \"Why your body needs a break after finishing, and five simple things that help you be ready again.\",\n    minutes: 3,\n    priority: 74,\n    tags: [\"round two\", \"kurudia tendo\", \"stamina\", \"recovery\", \"raundi\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DeKaV0iAuai/\", postedAt: \"2026-10-06\", format: \"carousel\" },\n    cover: { tone: \"night\", motif: \"waves\" },\n    body: [\n      \"After finishing, every man's body needs a rest before it can respond again. This pause is normal. It's usually shorter for younger men and gets longer with age.\",\n      \"## 1. Rest, but stay close\",\n      \"Don't turn over and sleep straight away. Keep touching, kissing and enjoying your partner while your body recovers. Closeness helps you both.\",\n      \"## 2. Drink water and breathe calmly\",\n      \"Being well hydrated and breathing slowly helps you feel refreshed.\",\n      \"## 3. Slow down in the first round\",\n      \"Learning to control your excitement in the first round — for example with the stop-start technique — can leave you less exhausted.\",\n      \"## 4. Fitness and sleep build stamina\",\n      \"Regular exercise, good sleep and good food all support your energy in bed.\",\n      \"## 5. A calm, confident mind\",\n      \"Pressure and worry make it harder to get aroused again. Focus on enjoyment, not performance.\",\n      \"If you used to recover easily and this has changed a lot, or you also have erection problems, it's worth talking to a doctor.\",\n    ],\n    bodySw: [\n      \"Baada ya kumaliza, mwili wa kila mwanaume unahitaji kupumzika kabla ya kuweza kusisimka tena. Mapumziko haya ni ya kawaida. Kwa kawaida huwa mafupi kwa vijana na huongezeka kadiri umri unavyoongezeka.\",\n      \"## 1. Pumzika, lakini baki karibu\",\n      \"Usigeuke na kulala moja kwa moja. Endelea kumshika, kumbusu na kufurahia mwenzako wakati mwili unajirudisha. Ukaribu huu unawasaidia nyote.\",\n      \"## 2. Kunywa maji na pumua kwa utulivu\",\n      \"Kuwa na maji ya kutosha mwilini na kupumua taratibu kunakusaidia kujisikia mpya tena.\",\n      \"## 3. Punguza kasi kwenye raundi ya kwanza\",\n      \"Ukijifunza kudhibiti msisimko kwenye raundi ya kwanza — kwa mfano kwa mbinu ya kusimama na kuendelea — hutachoka sana.\",\n      \"## 4. Mazoezi na usingizi huongeza stamina\",\n      \"Mazoezi ya mara kwa mara, usingizi mzuri na chakula bora vinasaidia nguvu zako.\",\n      \"## 5. Akili tulivu yenye kujiamini\",\n      \"Presha na wasiwasi hufanya iwe vigumu kusisimka tena. Lenga kufurahia, si kuonyesha uwezo.\",\n      \"Kama zamani ulikuwa unarudi haraka na sasa imebadilika sana, au una pia changamoto ya uume kusimama, ni vizuri kuongea na daktari.\",\n    ],\n  },\n  {\n    id: \"ig-gas-bloating-habits\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"Gas and bloating: three habits to start with\",\n    titleSw: \"Gesi na tumbo kujaa: tabia tatu za kuanza nazo\",\n    summary: \"Simple daily changes that often help a noisy, bloated stomach — and the signs that need a doctor.\",\n    minutes: 2,\n    priority: 66,\n    tags: [\"gas\", \"bloating\", \"digestion\", \"gesi\", \"tumbo\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdqbtIeAsdU/\", postedAt: \"2026-09-24\", format: \"carousel\" },\n    cover: { tone: \"mint\", motif: \"waves\" },\n    body: [\n      \"Is your stomach rumbling, full of gas, or are you struggling to pass stool? Start with three habits:\",\n      \"Eat your evening meal earlier, so your stomach has time to rest before sleep.\",\n      \"Walk for at least 10 minutes after eating.\",\n      \"Cut down on fatty, fried and heavily processed food.\",\n      \"Drinking enough water and eating more vegetables, fruit and whole grains also helps many people.\",\n      \"See a doctor if you notice blood in your stool, black stools, weight loss, ongoing pain, or if the problem lasts more than a few weeks.\",\n    ],\n    bodySw: [\n      \"Tumbo linaunguruma, linajaa gesi, au unapata choo kwa shida? Anza na tabia tatu:\",\n      \"Kula chakula cha jioni mapema, ili tumbo lipate muda wa kupumzika kabla ya kulala.\",\n      \"Tembea angalau dakika 10 baada ya kula.\",\n      \"Punguza vyakula vya mafuta mengi, vya kukaanga na vilivyosindikwa sana.\",\n      \"Kunywa maji ya kutosha na kula mboga, matunda na nafaka zisizokobolewa zaidi pia huwasaidia watu wengi.\",\n      \"Mwone daktari ukiona damu kwenye choo, choo cheusi, kupungua uzito, maumivu yasiyoisha, au kama tatizo linaendelea zaidi ya wiki chache.\",\n    ],\n  },\n  {\n    id: \"ig-beetroot-blood-flow\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Food for healthy blood flow: a beetroot drink\",\n    titleSw: \"Chakula kwa mzunguko mzuri wa damu: kinywaji cha beetroot\",\n    summary: \"Good blood flow matters for men's health. A simple drink using beetroot, pomegranate, honey and turmeric — as part of a healthy diet.\",\n    minutes: 2,\n    priority: 64,\n    tags: [\"beetroot\", \"blood flow\", \"nutrition\", \"lishe\", \"mzunguko wa damu\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdiS5Gygsb2/\", postedAt: \"2026-09-21\", format: \"carousel\" },\n    cover: { tone: \"clay\", motif: \"dots\" },\n    body: [\n      \"Men's health starts with good food. Healthy blood vessels and good circulation are important for erections and for the body as a whole.\",\n      \"Beetroot naturally contains nitrates, which the body can use to help blood vessels relax. Some studies suggest this supports blood flow. It's a helpful food, not a treatment.\",\n      \"## The drink\",\n      \"Mix 100–150 ml of beetroot juice with 1 tablespoon of pomegranate juice, 1 teaspoon of pure honey and a quarter to half a teaspoon of turmeric powder. Drink it in the morning or 30 minutes before a meal, 3–4 times a week.\",\n      \"## Take care\",\n      \"If you take medicine for blood pressure or diabetes, or blood thinners, check with a doctor or pharmacist first. Beetroot can turn urine pink or red — this is harmless.\",\n      \"If you have ongoing erection problems, food alone may not be enough. A doctor can check for causes like high blood pressure or diabetes.\",\n    ],\n    bodySw: [\n      \"Afya ya mwanaume huanza na lishe bora. Mishipa ya damu yenye afya na mzunguko mzuri wa damu ni muhimu kwa uume kusimama na kwa mwili mzima.\",\n      \"Beetroot (kiazi chekundu) kina nitrates kwa asili, ambazo mwili unaweza kuzitumia kusaidia mishipa ya damu kulegea. Baadhi ya tafiti zinaonyesha hii inasaidia mzunguko wa damu. Ni chakula chenye manufaa, si tiba.\",\n      \"## Kinywaji\",\n      \"Changanya juisi ya beetroot ml 100–150, kijiko 1 cha chakula cha juisi ya komamanga, kijiko 1 cha chai cha asali halisi, na robo hadi nusu kijiko cha chai cha binzari manjano. Kunywa asubuhi au dakika 30 kabla ya kula, mara 3–4 kwa wiki.\",\n      \"## Tahadhari\",\n      \"Kama unatumia dawa za presha, kisukari au za kuzuia damu kuganda, ongea na daktari au mfamasia kwanza. Beetroot inaweza kufanya mkojo kuwa wa pinki au mwekundu — hii haina madhara.\",\n      \"Kama una changamoto ya muda mrefu ya uume kusimama, chakula pekee kinaweza kisitoshe. Daktari anaweza kuchunguza visababishi kama presha au kisukari.\",\n    ],\n  },\n  {\n    id: \"ig-fertility-smoothie\",\n    kind: \"article\",\n    topic: \"fertility\",\n    title: \"A fertility-friendly smoothie\",\n    titleSw: \"Smoothie rafiki kwa afya ya uzazi\",\n    summary: \"Banana, almonds, avocado and milk bring nutrients sperm need — as part of a healthy lifestyle.\",\n    minutes: 2,\n    priority: 56,\n    tags: [\"fertility\", \"sperm\", \"smoothie\", \"mbegu za kiume\", \"uzazi\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdiTOo6qIo_/\", postedAt: \"2026-09-21\", format: \"post\" },\n    cover: { tone: \"mint\", motif: \"rings\" },\n    body: [\n      \"Healthy sperm need good nutrition over time — especially zinc, vitamin E, folate and antioxidants. This smoothie is an easy way to get some of them.\",\n      \"## Ingredients\",\n      \"1 large ripe banana, a handful of almonds, half an avocado and 1 glass of milk. Blend together. Add a little honey if you like.\",\n      \"## What each brings\",\n      \"Almonds: vitamin E and zinc. Avocado: healthy fats and folate. Banana: vitamin B6. Milk: calcium and protein.\",\n      \"## Keep it in perspective\",\n      \"No single food boosts fertility on its own. Sperm take about three months to develop, so steady habits matter: no smoking, less alcohol, a healthy weight and avoiding too much heat around the testicles.\",\n      \"If you and your partner have been trying for a year without success — or six months if she is over 35 — see a doctor together. A semen test is simple.\",\n    ],\n    bodySw: [\n      \"Mbegu za kiume zenye afya zinahitaji lishe bora kwa muda — hasa zinc, vitamini E, folate na antioxidants. Smoothie hii ni njia rahisi ya kupata baadhi yake.\",\n      \"## Mahitaji\",\n      \"Ndizi mbivu 1 kubwa, kiganja kimoja cha almond, nusu parachichi na glasi 1 ya maziwa. Saga pamoja kwenye blender. Ongeza asali kidogo ukipenda.\",\n      \"## Kila kimoja kinaleta nini\",\n      \"Almond: vitamini E na zinc. Parachichi: mafuta mazuri na folate. Ndizi: vitamini B6. Maziwa: calcium na protini.\",\n      \"## Kumbuka\",\n      \"Hakuna chakula kimoja kinachoongeza uwezo wa kuzaa peke yake. Mbegu huchukua takriban miezi mitatu kukua, hivyo tabia za kila siku ni muhimu: usivute sigara, punguza pombe, kuwa na uzito mzuri, na epuka joto kali karibu na korodani.\",\n      \"Kama wewe na mwenzako mmejaribu kwa mwaka mmoja bila mafanikio — au miezi sita kama yeye ana zaidi ya miaka 35 — mwoneni daktari pamoja. Kipimo cha mbegu ni rahisi.\",\n    ],\n  },\n];\n",
  "src/lib/content/library.ts": "// DEVELOPMENT FIXTURES — sample content until the Content Studio and database exist.\n// Every item is marked fixture: true and review: \"draft\". The UI shows this to readers.\n// Health wording rules: no cure claims, no guaranteed results, always say when to see a doctor.\n\nimport type { ContentItem, Topic } from \"./types\";\nimport { INSTAGRAM_CONTENT } from \"./instagram\";\n\nexport const TOPICS: Topic[] = [\n  { id: \"erection\", title: \"Erection health\", short: \"Erections\" },\n  { id: \"ejaculation\", title: \"Ejaculation and satisfaction\", short: \"Lasting longer\" },\n  { id: \"libido\", title: \"Libido and sexual desire\", short: \"Desire\" },\n  { id: \"fertility\", title: \"Fertility and sperm health\", short: \"Fertility\" },\n  { id: \"confidence\", title: \"Confidence and performance anxiety\", short: \"Confidence\" },\n  { id: \"intimacy\", title: \"Intimacy and relationships\", short: \"Intimacy\" },\n  { id: \"wellbeing\", title: \"Sleep, stress and physical wellbeing\", short: \"Body and mind\" },\n];\n\nconst DRAFT = \"Men's Social editorial · Draft, pending review by a qualified health professional\";\n\nconst EDITORIAL_SAMPLES: ContentItem[] = [\n  // ───────────── Erection health ─────────────\n  {\n    id: \"erection-guide\",\n    kind: \"guide\",\n    topic: \"erection\",\n    title: \"Erection health: what actually helps\",\n    summary: \"Understand what affects erections and the everyday changes with real evidence behind them — plus when to get checked.\",\n    minutes: 6,\n    priority: 100,\n    tags: [\"erectile dysfunction\", \"ED\", \"lifestyle\", \"blood flow\", \"heart\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"rings\" },\n    body: [\n      \"Almost every man has times when erections are weaker or don't last. One difficult night is normal. If it keeps happening for several weeks, it's worth paying attention — not with shame, but the way you would with any other health signal.\",\n      \"## How an erection works\",\n      \"An erection depends on healthy blood vessels, nerves, hormones and a relaxed mind working together. When any of these is under strain — from poor circulation, stress, tiredness, alcohol or some medicines — erections can be affected.\",\n      \"## Changes with good evidence\",\n      \"Regular physical activity: studies link moderate exercise, such as brisk walking several times a week, with better erectile function. It supports blood flow, weight and mood.\",\n      \"Stopping smoking: smoking damages blood vessels, including the small ones the penis depends on. Quitting helps your whole body.\",\n      \"Less alcohol: heavy drinking can make erections harder to get and keep, in the moment and over time.\",\n      \"Sleep and stress: long-term short sleep and constant stress can lower energy and desire. Small daily habits here often help more than people expect.\",\n      \"Managing health conditions: diabetes, high blood pressure and high cholesterol are common causes of erection problems. Keeping them under control matters.\",\n      \"## Be careful with 'instant' products\",\n      \"Be cautious with any product that promises instant or guaranteed results. Health authorities in several countries have found unregistered 'natural' sexual products that secretly contained prescription medicines, which can be dangerous — especially for men taking heart medicines.\",\n      \"## When to see a doctor\",\n      \"See a doctor if problems continue for more than a few weeks, if they started suddenly, or if you also have chest pain, shortness of breath, diabetes or high blood pressure. Erection problems can sometimes be an early sign of heart or blood-vessel disease, so a check-up is a smart move — and doctors deal with this every day.\",\n    ],\n  },\n  {\n    id: \"ed-heart-signal\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Why erection problems can be an early health signal\",\n    summary: \"The link between erections and heart health — and why a check-up can protect more than your sex life.\",\n    minutes: 3,\n    priority: 70,\n    tags: [\"heart\", \"blood pressure\", \"diabetes\", \"check-up\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"arc\" },\n    body: [\n      \"The blood vessels in the penis are small. When blood vessels around the body start to narrow, the small ones can show problems first.\",\n      \"That's why doctors often ask about erections when checking heart health — and why erection problems can sometimes appear years before other signs of heart disease.\",\n      \"A simple check-up can include blood pressure, blood sugar and cholesterol. If something is found early, it's usually easier to manage.\",\n      \"If you have erection problems together with chest pain, shortness of breath or swelling in the legs, see a doctor soon.\",\n    ],\n  },\n  {\n    id: \"quiz-erection-myths\",\n    kind: \"quiz\",\n    topic: \"erection\",\n    title: \"Erection health: myth or fact?\",\n    summary: \"Five quick questions. See what you know — and learn something new in two minutes.\",\n    minutes: 2,\n    priority: 60,\n    tags: [\"quiz\", \"myths\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"dots\" },\n    quiz: [\n      {\n        q: \"Occasional difficulty getting an erection means something is seriously wrong.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 0,\n        explain: \"Occasional difficulty is common and often linked to tiredness, stress or alcohol. Ongoing problems for several weeks are worth checking.\",\n      },\n      {\n        q: \"Regular exercise like brisk walking can support erection health.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"Studies link regular physical activity with better erectile function, partly through better blood flow.\",\n      },\n      {\n        q: \"Erection problems can sometimes be an early sign of heart disease.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"The small blood vessels in the penis can show problems early. That's why a check-up is a good idea.\",\n      },\n      {\n        q: \"Products that promise 'instant results' are always safe because they are natural.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 0,\n        explain: \"Some unregistered 'natural' products have been found to contain hidden medicines. Natural doesn't automatically mean safe.\",\n      },\n      {\n        q: \"Smoking can make erection problems more likely.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"Smoking damages blood vessels, including those needed for an erection.\",\n      },\n    ],\n  },\n  {\n    id: \"tool-doctor-check\",\n    kind: \"tool\",\n    topic: \"erection\",\n    title: \"Should I see a doctor? A quick check\",\n    summary: \"Answer a few yes/no questions to see whether a check-up is a good next step. Private — nothing is saved.\",\n    minutes: 1,\n    priority: 55,\n    tags: [\"doctor\", \"check-up\", \"tool\"],\n    tool: \"doctor-check\",\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"grid\" },\n  },\n  {\n    id: \"expert-instant-boosters\",\n    kind: \"expert\",\n    topic: \"erection\",\n    title: \"Are 'instant' sex boosters safe?\",\n    question: \"I see adverts for pills and powders that promise instant strength in bed. Are they safe to try?\",\n    summary: \"A clear answer on what to watch out for before you buy.\",\n    minutes: 2,\n    priority: 65,\n    tags: [\"supplements\", \"safety\", \"pills\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"sand\", motif: \"waves\" },\n    body: [\n      \"Be careful. Products that promise instant or guaranteed results are a warning sign.\",\n      \"Health authorities in several countries have found unregistered sexual-enhancement products — including some sold as 'herbal' — that secretly contained prescription medicines. These can cause dangerous drops in blood pressure, especially in men who take heart medicines called nitrates.\",\n      \"Before trying any product: check that it is registered with the national regulator (in Tanzania, TMDA), read the ingredients, and ask a pharmacist or doctor if you take any other medicines.\",\n      \"If erection problems are ongoing, a doctor can look for the cause and offer treatments that have been properly tested.\",\n    ],\n  },\n\n  // ───────────── Ejaculation and satisfaction ─────────────\n  {\n    id: \"lasting-longer\",\n    kind: \"guide\",\n    topic: \"ejaculation\",\n    title: \"Lasting longer: techniques with evidence\",\n    summary: \"Practical techniques you can try at home, explained simply — and what doctors can offer if you need more.\",\n    minutes: 5,\n    priority: 90,\n    tags: [\"premature ejaculation\", \"PE\", \"stop-start\", \"squeeze\", \"pelvic floor\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"waves\" },\n    body: [\n      \"Finishing earlier than you or your partner would like is one of the most common sexual concerns men have. It is not a sign of weakness, and it often improves with practice.\",\n      \"## The stop-start technique\",\n      \"During stimulation (alone or with a partner), stop when you feel you're getting close. Wait until the urge settles, then start again. Repeat a few times before allowing yourself to finish. Over time, many men learn to recognise and control the build-up better.\",\n      \"## The squeeze technique\",\n      \"Similar to stop-start, but when you're close, you or your partner gently squeeze the head of the penis for several seconds until the urge passes, then continue.\",\n      \"## Pelvic floor exercises\",\n      \"The pelvic floor muscles help control ejaculation. Some studies suggest that training them regularly can help. Try the Pelvic floor trainer tool in Discover.\",\n      \"## The mind matters\",\n      \"Anxiety can make finishing early more likely, and finishing early can increase anxiety. Slow breathing, focusing on touch and sensation, and talking openly with your partner can break that cycle.\",\n      \"## When to see a doctor\",\n      \"If it's causing you real distress, has always happened, or started suddenly, talk to a doctor. There are medical treatments, including medicines and numbing creams, that a doctor can discuss with you.\",\n    ],\n  },\n  {\n    id: \"too-early-myths\",\n    kind: \"article\",\n    topic: \"ejaculation\",\n    title: \"What counts as 'too early'? Common myths\",\n    summary: \"Films and friends set unrealistic expectations. Here's what's actually normal.\",\n    minutes: 3,\n    priority: 50,\n    tags: [\"myths\", \"normal\", \"expectations\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"arc\" },\n    body: [\n      \"Many men believe sex should last much longer than it usually does. Films and stories from friends often give a false picture.\",\n      \"What matters most is whether you and your partner are satisfied — not a number on a clock.\",\n      \"Finishing quickly from time to time, especially after a long break, when very excited, or with a new partner, is common.\",\n      \"If it happens almost every time and causes you or your partner distress, that's worth addressing. Start with the techniques in 'Lasting longer', and see a doctor if it continues.\",\n    ],\n  },\n  {\n    id: \"tool-pelvic-floor\",\n    kind: \"tool\",\n    topic: \"ejaculation\",\n    title: \"Pelvic floor trainer\",\n    summary: \"A guided timer for pelvic floor exercises: squeeze, hold, relax. Takes about three minutes.\",\n    minutes: 3,\n    priority: 58,\n    tags: [\"kegel\", \"pelvic floor\", \"exercise\", \"tool\"],\n    tool: \"pelvic-floor\",\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"dots\" },\n  },\n  {\n    id: \"video-pelvic-floor\",\n    kind: \"video\",\n    topic: \"ejaculation\",\n    title: \"Pelvic floor muscles, explained\",\n    summary: \"Where these muscles are, how to find them, and why they matter for control.\",\n    minutes: 2,\n    priority: 52,\n    tags: [\"video\", \"pelvic floor\", \"kegel\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"rings\" },\n    keyPoints: [\n      \"The pelvic floor is a group of muscles under your bladder and bowel.\",\n      \"To find them, imagine stopping yourself from passing wind — that's the squeeze.\",\n      \"Don't hold your breath or tighten your stomach, legs or bottom.\",\n      \"Start with a few short squeezes and build up slowly.\",\n      \"Stop and see a doctor if you feel pain.\",\n    ],\n  },\n  {\n    id: \"expert-normal-quickly\",\n    kind: \"expert\",\n    topic: \"ejaculation\",\n    title: \"Is it normal to finish quickly sometimes?\",\n    question: \"Sometimes I finish within a minute, other times it's fine. Should I be worried?\",\n    summary: \"What a changing pattern usually means, and when it's worth getting help.\",\n    minutes: 2,\n    priority: 48,\n    tags: [\"premature ejaculation\", \"normal\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"sand\", motif: \"grid\" },\n    body: [\n      \"Yes, it's common for timing to vary. Excitement, a long break, a new partner, stress or alcohol can all change it.\",\n      \"Because it's fine at other times, this is usually not a fixed problem. Techniques like stop-start and pelvic floor exercises can help you feel more in control.\",\n      \"If it starts happening almost every time, or it's causing you or your partner real distress, it's worth speaking to a doctor.\",\n    ],\n  },\n\n  // ───────────── Libido and reproductive health ─────────────\n  {\n    id: \"low-desire\",\n    kind: \"article\",\n    topic: \"libido\",\n    title: \"Low desire: common causes and what to check\",\n    summary: \"Why interest in sex changes, what you can look at yourself, and when a blood test makes sense.\",\n    minutes: 4,\n    priority: 75,\n    tags: [\"libido\", \"desire\", \"testosterone\", \"stress\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"waves\" },\n    body: [\n      \"Desire goes up and down for every man. Work pressure, money worries, poor sleep, relationship tension and tiredness are some of the most common reasons it drops.\",\n      \"## Things you can look at\",\n      \"Sleep, stress, alcohol, exercise and how things are in your relationship. Tracking your energy and sleep in the Man tab can help you spot patterns.\",\n      \"## Medicines and health\",\n      \"Some medicines, including some for blood pressure and depression, can affect desire. Don't stop a prescribed medicine on your own — talk to your doctor about options.\",\n      \"## What about testosterone?\",\n      \"Low testosterone can reduce desire, but it can only be confirmed with a blood test, usually taken in the morning. Taking testosterone or 'booster' products without a doctor can cause side effects and can reduce fertility.\",\n      \"If low desire lasts for months or worries you, a doctor can help find the cause.\",\n    ],\n  },\n  {\n    id: \"fertility-basics\",\n    kind: \"article\",\n    topic: \"fertility\",\n    title: \"Fertility basics for men\",\n    summary: \"Simple facts about male fertility and the everyday habits that help protect it.\",\n    minutes: 4,\n    priority: 62,\n    tags: [\"fertility\", \"sperm\", \"children\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"rings\" },\n    body: [\n      \"When a couple has difficulty having a baby, the cause is linked to the man in a large share of cases. Checking both partners is normal and sensible.\",\n      \"## Habits that help protect sperm\",\n      \"Avoid smoking, limit alcohol, keep a healthy weight, and avoid long periods of heat around the testicles, such as very hot baths or a laptop on your lap.\",\n      \"Muscle-building steroids and testosterone products can seriously reduce sperm production.\",\n      \"## When to get checked\",\n      \"If you and your partner have been trying for a year without success — or six months if she is over 35 — see a doctor together. A semen test is simple and gives useful information.\",\n    ],\n  },\n  {\n    id: \"expert-masturbation\",\n    kind: \"expert\",\n    topic: \"libido\",\n    title: \"Does masturbation cause erection problems?\",\n    question: \"People say masturbating too much makes you weak. Is that true?\",\n    summary: \"A calm, honest answer to one of the most common questions men ask.\",\n    minutes: 2,\n    priority: 68,\n    tags: [\"masturbation\", \"myths\", \"habits\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"arc\" },\n    body: [\n      \"Masturbation is a normal part of sexual health for many men, and there's no good evidence that it causes erection problems or physical weakness.\",\n      \"What can matter is the pattern. If it feels out of control, gets in the way of daily life or your relationship, or if you rely on very specific content to get aroused, it may affect how you respond with a partner.\",\n      \"If you'd like to change a habit, that's a personal choice and it's fine. Small steps work better than guilt. If erection problems continue, see a doctor to check for other causes.\",\n    ],\n  },\n\n  // ───────────── Confidence and performance anxiety ─────────────\n  {\n    id: \"performance-anxiety\",\n    kind: \"guide\",\n    topic: \"confidence\",\n    title: \"Performance anxiety: breaking the cycle\",\n    summary: \"Why worrying about sex can make things harder — and practical ways to get out of your head.\",\n    minutes: 5,\n    priority: 85,\n    tags: [\"anxiety\", \"confidence\", \"nerves\", \"pressure\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"waves\" },\n    body: [\n      \"One bad experience can make you worry about the next time. That worry puts your body on alert, which makes it harder to relax and respond — and the cycle continues.\",\n      \"## Shift the focus\",\n      \"Focus on touch, closeness and enjoyment rather than 'performing'. Sex doesn't have to follow a script or end in a particular way.\",\n      \"## Calm the body first\",\n      \"A few minutes of slow breathing — in for 4 seconds, out for 6 — can calm the alert response. Try the 2-minute breathing video in Discover.\",\n      \"## Talk about it\",\n      \"Telling your partner you've been feeling pressure often takes much of the weight away. Most partners care more about connection than performance.\",\n      \"## Get support if it continues\",\n      \"If anxiety is affecting your relationships or daily life, a doctor or counsellor can help. Asking for help is a strong move.\",\n    ],\n  },\n  {\n    id: \"stress-and-performance\",\n    kind: \"article\",\n    topic: \"confidence\",\n    title: \"Stress, worry and performance\",\n    summary: \"How a busy mind can affect confidence in the bedroom, and what helps.\",\n    minutes: 4,\n    priority: 45,\n    tags: [\"stress\", \"anxiety\", \"performance\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"sand\", motif: \"dots\" },\n    body: [\n      \"Many men go through periods where worry or stress affects their confidence or sexual performance. It is common and nothing to be ashamed of.\",\n      \"When you are anxious, your body goes into 'alert' mode. That can make it harder to relax and stay in the moment.\",\n      \"Calming habits can help: slow breathing, regular exercise, enough sleep, and talking openly with your partner.\",\n      \"If problems with erections or finishing too early continue for several weeks, speak with a doctor. These can sometimes be linked to blood pressure, diabetes or other conditions that are worth checking.\",\n    ],\n  },\n  {\n    id: \"video-breathing-reset\",\n    kind: \"video\",\n    topic: \"confidence\",\n    title: \"A 2-minute breathing reset\",\n    summary: \"A simple breathing pattern to calm nerves before an important moment.\",\n    minutes: 2,\n    priority: 50,\n    tags: [\"video\", \"breathing\", \"calm\", \"nerves\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"rings\" },\n    keyPoints: [\n      \"Sit or lie comfortably and relax your shoulders.\",\n      \"Breathe in through your nose for 4 seconds.\",\n      \"Breathe out slowly through your mouth for 6 seconds.\",\n      \"Repeat for about 2 minutes.\",\n      \"A longer out-breath helps the body switch out of 'alert' mode.\",\n    ],\n  },\n\n  // ───────────── Intimacy and relationships ─────────────\n  {\n    id: \"talk-to-partner\",\n    kind: \"guide\",\n    topic: \"intimacy\",\n    title: \"How to talk to your partner about sex and health\",\n    summary: \"Simple ways to start a difficult conversation — without blame, and without it turning into a fight.\",\n    minutes: 4,\n    priority: 72,\n    tags: [\"communication\", \"partner\", \"relationship\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"grid\" },\n    body: [\n      \"Many couples never talk about sex directly. Small worries then grow into distance.\",\n      \"## Choose the moment\",\n      \"Talk at a calm time — not in bed straight after something went wrong, and not when either of you is tired or angry.\",\n      \"## Start with 'I', not 'you'\",\n      \"'I've been feeling stressed and it's affecting me' is easier to hear than 'You make me nervous'.\",\n      \"## Listen as much as you talk\",\n      \"Ask what she enjoys and what she'd like more of. Intimacy is a shared thing.\",\n      \"## Make a plan together\",\n      \"Agreeing on small changes — more time together, less pressure, seeing a doctor together — can bring you closer.\",\n    ],\n  },\n  {\n    id: \"expert-partner-reaction\",\n    kind: \"expert\",\n    topic: \"intimacy\",\n    title: \"How do I tell my partner I'm seeing a doctor about this?\",\n    question: \"I want to see a doctor about erection problems but I'm embarrassed to tell my wife. How should I bring it up?\",\n    summary: \"Ideas for an honest conversation that brings you closer.\",\n    minutes: 2,\n    priority: 40,\n    tags: [\"partner\", \"doctor\", \"communication\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"waves\" },\n    body: [\n      \"Seeing a doctor shows that you care about your health and your relationship. Many partners feel relieved, because they may have been worrying it was about them.\",\n      \"You could say: 'I've noticed things haven't been easy for me lately, and I want to get it checked so we can enjoy each other more.'\",\n      \"Some couples choose to go to the appointment together. That's completely fine and can help.\",\n    ],\n  },\n\n  // ───────────── Sleep, stress and physical wellbeing ─────────────\n  {\n    id: \"sleep-and-energy\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"How sleep shapes your energy\",\n    summary: \"Why a few short nights can leave you drained, and simple ways to sleep better.\",\n    minutes: 3,\n    priority: 60,\n    tags: [\"sleep\", \"energy\", \"rest\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"night\", motif: \"arc\" },\n    body: [\n      \"Sleep is when your body recovers. After several short nights, many men notice lower energy, a shorter temper and less interest in exercise or intimacy.\",\n      \"Research has linked ongoing short sleep with changes in hormones and mood. Everyone is different, but most adults feel best with around 7 to 9 hours.\",\n      \"Small habits help: going to bed at a similar time each night, keeping the room dark and cool, and putting screens away before bed.\",\n      \"Track your sleep for a couple of weeks and compare it with your energy check-ins. Patterns are often easier to see than to feel.\",\n      \"See a doctor if you snore loudly, stop breathing during sleep, or feel exhausted even after a full night. These can be signs of a sleep condition.\",\n    ],\n  },\n  {\n    id: \"how-much-water\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"How much water do you need?\",\n    summary: \"There's no single number. Here's how to find what works for you.\",\n    minutes: 2,\n    priority: 35,\n    tags: [\"water\", \"hydration\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"mint\", motif: \"dots\" },\n    body: [\n      \"Your water needs depend on your body size, how active you are and the weather. Hot days and exercise mean you need more.\",\n      \"Many adults aim for around 2 to 3 litres a day from drinks, but food provides some water too.\",\n      \"A simple check: pale yellow urine usually means you're drinking enough. Dark urine, headaches or feeling tired can be signs you need more.\",\n      \"If you have kidney or heart problems, ask a doctor how much you should drink.\",\n    ],\n  },\n  {\n    id: \"walking-benefits\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"The 20-minute walk: small habit, big return\",\n    summary: \"Why a daily walk is one of the simplest things you can do for energy, mood and circulation.\",\n    minutes: 3,\n    priority: 42,\n    tags: [\"walking\", \"exercise\", \"circulation\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"grid\" },\n    body: [\n      \"You don't need a gym to look after your body. Regular walking supports heart health, circulation, weight and mood.\",\n      \"Aim for a pace where you can talk but not sing. Twenty minutes most days is a great start.\",\n      \"If walking alone is hard to keep up, make it social: walk with a friend, or after dinner with your family.\",\n      \"If you have chest pain or feel very short of breath when walking, stop and see a doctor.\",\n    ],\n  },\n];\n\n/** Everything in Discover: real content adapted from Instagram, plus editorial samples. */\nexport const LIBRARY: ContentItem[] = [...INSTAGRAM_CONTENT, ...EDITORIAL_SAMPLES];\n",
  "src/lib/content/rows.ts": "// Converts between a database row (snake_case) and the app's ContentItem.\n// Defensive: bad or missing values from the database never crash the app.\n\nimport type { ContentItem, ContentKind, ContentStatus, QuizQuestion, ToolId, TopicId } from \"./types\";\n\nexport interface ContentRow {\n  id: string;\n  status: ContentStatus;\n  kind: ContentKind;\n  topic: TopicId;\n  title: string;\n  title_sw: string | null;\n  summary: string;\n  minutes: number;\n  priority: number;\n  tags: string[];\n  body: string[];\n  body_sw: string[];\n  key_points: string[];\n  question: string | null;\n  quiz: QuizQuestion[] | null;\n  tool: ToolId | null;\n  source: string;\n  review: \"draft\" | \"reviewed\";\n  cover: ContentItem[\"cover\"];\n  cover_image_url: string | null;\n  origin: ContentItem[\"origin\"] | null;\n  in_man_feed: boolean;\n  points: number;\n  updated_at?: string;\n}\n\nconst KINDS: ContentKind[] = [\"guide\", \"article\", \"video\", \"quiz\", \"tool\", \"expert\"];\nconst TOPICS: TopicId[] = [\"erection\", \"ejaculation\", \"libido\", \"fertility\", \"confidence\", \"intimacy\", \"wellbeing\"];\nconst strArr = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === \"string\") : []);\n\nexport function rowToItem(row: Partial<ContentRow>): ContentItem | null {\n  if (!row.id || !row.title || !KINDS.includes(row.kind as ContentKind) || !TOPICS.includes(row.topic as TopicId)) {\n    return null;\n  }\n  const body = strArr(row.body);\n  const bodySw = strArr(row.body_sw);\n  const keyPoints = strArr(row.key_points);\n  return {\n    id: row.id,\n    status: row.status ?? \"draft\",\n    kind: row.kind as ContentKind,\n    topic: row.topic as TopicId,\n    title: row.title,\n    titleSw: row.title_sw || undefined,\n    summary: row.summary ?? \"\",\n    minutes: Number(row.minutes) || 3,\n    priority: Number.isFinite(row.priority) ? Number(row.priority) : 50,\n    tags: strArr(row.tags),\n    body: body.length ? body : undefined,\n    bodySw: bodySw.length ? bodySw : undefined,\n    keyPoints: keyPoints.length ? keyPoints : undefined,\n    question: row.question || undefined,\n    quiz: Array.isArray(row.quiz) && row.quiz.length ? row.quiz : undefined,\n    tool: row.tool || undefined,\n    source: row.source || \"Men's Social editorial\",\n    review: row.review === \"reviewed\" ? \"reviewed\" : \"draft\",\n    fixture: false,\n    cover: row.cover && typeof row.cover === \"object\" ? row.cover : { tone: \"forest\", motif: \"rings\" },\n    coverImageUrl: row.cover_image_url || undefined,\n    origin: row.origin || undefined,\n    inManFeed: Boolean(row.in_man_feed),\n    points: Number(row.points) || 10,\n    updatedAt: row.updated_at,\n    builtIn: false,\n  };\n}\n\nexport function itemToRow(item: ContentItem, status: ContentStatus): Omit<ContentRow, \"updated_at\"> {\n  return {\n    id: item.id,\n    status,\n    kind: item.kind,\n    topic: item.topic,\n    title: item.title.trim(),\n    title_sw: item.titleSw?.trim() || null,\n    summary: item.summary.trim(),\n    minutes: item.minutes,\n    priority: item.priority,\n    tags: item.tags,\n    body: item.body ?? [],\n    body_sw: item.bodySw ?? [],\n    key_points: item.keyPoints ?? [],\n    question: item.question?.trim() || null,\n    quiz: item.quiz ?? null,\n    tool: item.tool ?? null,\n    source: item.source.trim(),\n    review: item.review,\n    cover: item.cover,\n    cover_image_url: item.coverImageUrl ?? null,\n    origin: item.origin ?? null,\n    in_man_feed: Boolean(item.inManFeed),\n    points: item.points ?? 10,\n  };\n}\n\n/** Built-in items, with anything published in the Studio added — a published copy replaces the built-in one. */\nexport function mergeLibrary(builtIn: ContentItem[], published: ContentItem[]): ContentItem[] {\n  const byId = new Map<string, ContentItem>();\n  for (const c of builtIn) byId.set(c.id, { ...c, builtIn: true, status: \"published\" });\n  for (const c of published) if (c.status === \"published\") byId.set(c.id, c);\n  return [...byId.values()];\n}\n",
  "src/lib/content/select.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { LIBRARY } from \"./library\";\nimport { featuredToday, orderSections, pickFeatured, questionToday, quickVideos, recommendations, searchContent, sectionAll, sectionItems, SECTIONS, topicTiles, type Personal } from \"./select\";\nimport type { ContentItem } from \"./types\";\n\ndescribe(\"content library\", () => {\n  it(\"has unique ids, and every item shows its source and draft status\", () => {\n    const ids = LIBRARY.map((c) => c.id);\n    expect(new Set(ids).size).toBe(ids.length);\n    expect(LIBRARY.every((c) => c.review === \"draft\" && c.source.length > 0)).toBe(true);\n  });\n  it(\"real (non-sample) items link back to where they came from, with a Kiswahili version\", () => {\n    for (const c of LIBRARY.filter((x) => !x.fixture)) {\n      expect(c.origin?.url, c.id).toMatch(/^https:\\/\\/www\\.instagram\\.com\\//);\n      expect(c.bodySw?.length, c.id).toBe(c.body?.length);\n      expect(c.titleSw, c.id).toBeTruthy();\n    }\n  });\n  it(\"never promises cures or guaranteed results\", () => {\n    const text = JSON.stringify(LIBRARY).toLowerCase();\n    for (const banned of [\"guaranteed to\", \"guarantees\", \"100%\", \"will cure\", \"cures erectile\", \"permanent cure\", \"miracle\", \"unatibu\", \"inatibu\", \"huponya\", \"kutibu kabisa\", \"tsh\", \"0655\", \"0635\", \"kayapower\", \"whatsapp\"]) {\n      expect(text.includes(banned), banned).toBe(false);\n    }\n  });\n  it(\"quizzes have valid answers and tools have a tool id\", () => {\n    for (const c of LIBRARY) {\n      if (c.kind === \"quiz\") c.quiz!.forEach((q) => expect(q.answer).toBeLessThan(q.options.length));\n      if (c.kind === \"tool\") expect(c.tool).toBeTruthy();\n    }\n  });\n  it(\"fills all ten topic pages (7 topics incl. Fertility + 3 formats)\", () => {\n    expect(SECTIONS).toHaveLength(10);\n    for (const s of SECTIONS) expect(sectionItems(s.id).length, s.id).toBeGreaterThan(0);\n  });\n});\n\ndescribe(\"featured content\", () => {\n  it(\"prefers real content over samples when he has no interests\", () => {\n    expect(pickFeatured([])?.fixture).toBe(false);\n  });\n  it(\"uses samples only when there is no real content\", () => {\n    expect(pickFeatured([], LIBRARY.filter((c) => c.fixture))?.id).toBe(\"erection-guide\");\n  });\n  it(\"favours a topic he chose\", () => {\n    expect(pickFeatured([\"intimacy\"])?.topic).toBe(\"intimacy\");\n    expect(pickFeatured([\"ejaculation\"])?.topic).toBe(\"ejaculation\");\n  });\n  it(\"only features reading content (guides and articles)\", () => {\n    expect([\"guide\", \"article\"]).toContain(pickFeatured([\"libido\"])?.kind);\n  });\n  it(\"returns null when there is no content\", () => {\n    expect(pickFeatured([], [])).toBeNull();\n  });\n  it(\"does not repeat the featured item in its section row\", () => {\n    expect(sectionItems(\"erection\", \"erection-guide\").some((c) => c.id === \"erection-guide\")).toBe(false);\n  });\n});\n\ndescribe(\"sections and search\", () => {\n  it(\"topic pages include every format for that topic\", () => {\n    const kinds = new Set(sectionAll(\"erection\").map((c) => c.kind));\n    expect(kinds.has(\"quiz\") && kinds.has(\"tool\") && kinds.has(\"expert\")).toBe(true);\n  });\n  it(\"puts his chosen topics first\", () => {\n    expect(orderSections([\"intimacy\"])[0].id).toBe(\"intimacy\");\n  });\n  it(\"finds content by words in titles, tags and text\", () => {\n    expect(searchContent(\"pelvic floor\").map((c) => c.id)).toContain(\"tool-pelvic-floor\");\n    expect(searchContent(\"fertility\")[0].id).toBe(\"fertility-basics\");\n    expect(searchContent(\"TMDA\").map((c) => c.id)).toContain(\"expert-instant-boosters\");\n  });\n  it(\"needs every word to match, and ignores empty searches\", () => {\n    expect(searchContent(\"pelvic zzzz\")).toEqual([]);\n    expect(searchContent(\"  \")).toEqual([]);\n  });\n  it(\"works on any list (e.g. a future database result)\", () => {\n    const one = [{ ...LIBRARY[0], id: \"x\", title: \"Hello world\" } as ContentItem];\n    expect(searchContent(\"hello\", one)).toHaveLength(1);\n  });\n});\n\ndescribe(\"Kiswahili search\", () => {\n  it(\"finds content by Kiswahili words\", () => {\n    const ids = searchContent(\"gesi tumbo\").map((c) => c.id);\n    expect(ids).toContain(\"ig-eating-day-calm-stomach\");\n    expect(ids).toContain(\"ig-gas-bloating-habits\");\n    expect(searchContent(\"kurudia tendo\")[0].id).toBe(\"ig-second-round\");\n  });\n});\n\nconst none: Personal = { interests: [], bookmarks: {}, history: {} };\n\ndescribe(\"Discover home: show less, deliver more\", () => {\n  it(\"featured rotates daily among the best few, and avoids what he already read\", () => {\n    const days = new Set([0, 1, 2, 3].map((d) => featuredToday(none, LIBRARY, d)?.id));\n    expect(days.size).toBeGreaterThan(1);\n    const today = featuredToday(none, LIBRARY, 5)!;\n    expect(featuredToday({ ...none, history: { [today.id]: \"x\" } }, LIBRARY, 5)?.id).not.toBe(today.id);\n  });\n  it(\"gives a new man three good starting points from different topics\", () => {\n    const r = recommendations(none, LIBRARY);\n    expect(r).toHaveLength(3);\n    expect(new Set(r.map((x) => x.item.topic)).size).toBe(3);\n    expect(r.every((x) => x.reason === \"A good place to start\")).toBe(true);\n  });\n  it(\"recommends his chosen topic first and says why\", () => {\n    const r = recommendations({ ...none, interests: [\"fertility\"] }, LIBRARY);\n    expect(r[0].item.topic).toBe(\"fertility\");\n    expect(r[0].reason).toBe(\"Because you follow Fertility\");\n  });\n  it(\"learns from what he saves and reads, and skips what he already read\", () => {\n    const read = LIBRARY.find((c) => c.id === \"lasting-longer\")!;\n    const r = recommendations({ ...none, history: { [read.id]: \"x\" } }, LIBRARY);\n    expect(r.some((x) => x.item.id === read.id)).toBe(false);\n    expect(r.some((x) => x.item.topic === \"ejaculation\" && x.reason.startsWith(\"Because you read\"))).toBe(true);\n  });\n  it(\"never repeats the featured item\", () => {\n    const f = featuredToday(none, LIBRARY, 0)!;\n    expect(recommendations(none, LIBRARY, [f.id]).some((x) => x.item.id === f.id)).toBe(false);\n  });\n  it(\"shows at most two short videos and one question\", () => {\n    expect(quickVideos(none, LIBRARY).length).toBeLessThanOrEqual(2);\n    expect(quickVideos(none, LIBRARY).every((c) => c.kind === \"video\")).toBe(true);\n    expect(questionToday(none, LIBRARY, 0)?.kind).toBe(\"expert\");\n  });\n  it(\"keeps the whole library reachable through topic pages\", () => {\n    const tiles = topicTiles(LIBRARY);\n    expect(tiles.find((t) => t.id === \"fertility\")?.count).toBeGreaterThan(0);\n    const reachable = new Set(tiles.flatMap((t) => sectionAll(t.id, LIBRARY).map((c) => c.id)));\n    expect(LIBRARY.every((c) => reachable.has(c.id))).toBe(true);\n  });\n});\n",
  "src/lib/content/select.ts": "// Chooses and finds content. Pure functions — no saving here, easy to test.\n\nimport type { ContentItem, ContentKind, TopicId } from \"./types\";\nimport { LIBRARY, TOPICS } from \"./library\";\n\nexport type SectionId = TopicId | \"expert\" | \"videos\" | \"tools\";\n\nexport const SECTIONS: { id: SectionId; title: string; blurb: string }[] = [\n  ...TOPICS.map((t) => ({ id: t.id as SectionId, title: t.title, blurb: \"\" })),\n  { id: \"expert\", title: \"Expert answers\", blurb: \"Real questions men ask, answered clearly.\" },\n  { id: \"videos\", title: \"Short videos\", blurb: \"Two minutes or less.\" },\n  { id: \"tools\", title: \"Quizzes and practical tools\", blurb: \"Learn by doing.\" },\n];\n\nconst READING: ContentKind[] = [\"guide\", \"article\"];\n\nexport function getContent(id: string, library: ContentItem[] = LIBRARY): ContentItem | undefined {\n  return library.find((c) => c.id === id);\n}\n\nexport function sectionTitle(id: string): string | undefined {\n  return SECTIONS.find((s) => s.id === id)?.title;\n}\n\nexport function isSectionId(id: string): id is SectionId {\n  return SECTIONS.some((s) => s.id === id);\n}\n\n/**\n * Featured item: highest editorial priority among guides/articles,\n * boosted when it matches a topic he chose, and when it's real content rather than a sample.\n * Ties broken by id so it's stable.\n */\nexport function pickFeatured(interests: TopicId[], library: ContentItem[] = LIBRARY): ContentItem | null {\n  const candidates = library.filter((c) => READING.includes(c.kind));\n  if (candidates.length === 0) return null;\n  const score = (c: ContentItem) =>\n    c.priority + (interests.includes(c.topic) ? 60 : 0) + (c.kind === \"guide\" ? 5 : 0) + (c.fixture ? 0 : 30);\n  return [...candidates].sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id))[0];\n}\n\n/** Items for a row on Discover. Topic rows show reading content; format rows show that format. */\nexport function sectionItems(id: SectionId, excludeId?: string, library: ContentItem[] = LIBRARY): ContentItem[] {\n  const pick =\n    id === \"expert\"\n      ? library.filter((c) => c.kind === \"expert\")\n      : id === \"videos\"\n        ? library.filter((c) => c.kind === \"video\")\n        : id === \"tools\"\n          ? library.filter((c) => c.kind === \"quiz\" || c.kind === \"tool\")\n          : library.filter((c) => c.topic === id && READING.includes(c.kind));\n  return pick.filter((c) => c.id !== excludeId).sort((a, b) => b.priority - a.priority);\n}\n\n/** Everything for a topic page (all formats), or a format page. */\nexport function sectionAll(id: SectionId, library: ContentItem[] = LIBRARY): ContentItem[] {\n  if (id === \"expert\" || id === \"videos\" || id === \"tools\") return sectionItems(id, undefined, library);\n  return library.filter((c) => c.topic === id).sort((a, b) => b.priority - a.priority);\n}\n\n/** Order sections so the ones he cares about come first (stable otherwise). */\nexport function orderSections(interests: TopicId[]) {\n  return [...SECTIONS].sort((a, b) => {\n    const ai = interests.includes(a.id as TopicId) ? 0 : 1;\n    const bi = interests.includes(b.id as TopicId) ? 0 : 1;\n    return ai - bi;\n  });\n}\n\nconst norm = (s: string) => s.toLowerCase().normalize(\"NFKD\").replace(/[^\\p{L}\\p{N}\\s]/gu, \" \");\n\n/** Search across titles, tags, summaries, questions and text. Every word must match somewhere. */\nexport function searchContent(query: string, library: ContentItem[] = LIBRARY): ContentItem[] {\n  const words = norm(query).split(/\\s+/).filter((w) => w.length > 1);\n  if (words.length === 0) return [];\n  const topicTitle = (id: TopicId) => TOPICS.find((t) => t.id === id)?.title ?? \"\";\n\n  const scored = library.map((c) => {\n    const title = norm(c.title);\n    const tags = norm(c.tags.join(\" \") + \" \" + topicTitle(c.topic) + \" \" + c.kind);\n    const rest = norm(\n      [c.summary, c.question ?? \"\", c.titleSw ?? \"\", ...(c.body ?? []), ...(c.bodySw ?? []), ...(c.keyPoints ?? [])].join(\" \"),\n    );\n    let score = 0;\n    for (const w of words) {\n      const s = (title.includes(w) ? 3 : 0) + (tags.includes(w) ? 2 : 0) + (rest.includes(w) ? 1 : 0);\n      if (s === 0) return { c, score: 0 };\n      score += s;\n    }\n    return { c, score: score + c.priority / 1000 };\n  });\n\n  return scored.filter((x) => x.score > 0).sort((a, b) => b.score - a.score).map((x) => x.c);\n}\n\nexport const KIND_LABEL: Record<ContentKind, string> = {\n  guide: \"Guide\",\n  article: \"Article\",\n  video: \"Video\",\n  quiz: \"Quiz\",\n  tool: \"Tool\",\n  expert: \"Expert answer\",\n};\n\nexport const CTA_LABEL: Record<ContentKind, string> = {\n  guide: \"Explore guide\",\n  article: \"Read article\",\n  video: \"Watch\",\n  quiz: \"Start quiz\",\n  tool: \"Open tool\",\n  expert: \"Read answer\",\n};\n\n/* ───────────── Discover home: show less, deliver more ───────────── */\n\nexport interface Personal {\n  interests: TopicId[];\n  /** contentId → when he saved it */\n  bookmarks: Record<string, string>;\n  /** contentId → when he last opened it */\n  history: Record<string, string>;\n}\n\n/** Day number, so daily picks change once a day (not on every visit). */\nexport const dayNumber = (d = new Date()) => Math.floor((d.getTime() - d.getTimezoneOffset() * 60000) / 86400000);\n\n/** Topics he has shown interest in by saving or reading (not only the ones he ticked). */\nfunction engagedTopics(p: Personal, library: ContentItem[]): Map<TopicId, number> {\n  const weight = new Map<TopicId, number>();\n  const add = (id: string, w: number) => {\n    const c = library.find((x) => x.id === id);\n    if (c) weight.set(c.topic, (weight.get(c.topic) ?? 0) + w);\n  };\n  Object.keys(p.bookmarks).forEach((id) => add(id, 2));\n  Object.keys(p.history).forEach((id) => add(id, 1));\n  return weight;\n}\n\n/**\n * Featured insight that rotates daily among the best few candidates, so the top of Discover\n * isn't the same forever. Prefers things he hasn't opened yet.\n */\nexport function featuredToday(p: Personal, library: ContentItem[], day = dayNumber()): ContentItem | null {\n  const candidates = library.filter((c) => READING.includes(c.kind));\n  if (!candidates.length) return null;\n  const score = (c: ContentItem) =>\n    c.priority + (p.interests.includes(c.topic) ? 60 : 0) + (c.kind === \"guide\" ? 5 : 0) + (c.fixture ? 0 : 30) - (p.history[c.id] ? 70 : 0);\n  const top = [...candidates].sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id)).slice(0, 3);\n  return top[day % top.length];\n}\n\nexport interface Recommendation {\n  item: ContentItem;\n  /** Shown under the card, so he knows why it's there. */\n  reason: string;\n}\n\n/**\n * Two or three picks for him. Based on the topics he chose, what he saved and read;\n * skips what he already read and the featured item; mixes topics so it's not three of the same.\n * New men get a balanced set of good starting points.\n */\nexport function recommendations(p: Personal, library: ContentItem[], exclude: string[] = [], count = 3): Recommendation[] {\n  const engaged = engagedTopics(p, library);\n  const isNew = p.interests.length === 0 && engaged.size === 0;\n  const pool = library.filter((c) => (READING.includes(c.kind) || c.kind === \"tool\" || c.kind === \"quiz\") && !exclude.includes(c.id) && !p.history[c.id]);\n\n  const reasonFor = (c: ContentItem): { score: number; reason: string } => {\n    const topic = TOPICS.find((t) => t.id === c.topic)?.short ?? \"\";\n    if (p.interests.includes(c.topic)) return { score: c.priority + 100, reason: `Because you follow ${topic}` };\n    const e = engaged.get(c.topic) ?? 0;\n    if (e > 0) return { score: c.priority + 40 + e * 10, reason: `Because you read about ${topic.toLowerCase()}` };\n    return { score: c.priority, reason: isNew ? \"A good place to start\" : \"Popular with men like you\" };\n  };\n\n  const ranked = pool\n    .map((item) => ({ item, ...reasonFor(item) }))\n    .sort((a, b) => b.score - a.score || a.item.id.localeCompare(b.item.id));\n\n  // Mix topics: at most one per topic first, then fill up if needed\n  const picked: typeof ranked = [];\n  for (const r of ranked) if (picked.length < count && !picked.some((x) => x.item.topic === r.item.topic)) picked.push(r);\n  for (const r of ranked) if (picked.length < count && !picked.includes(r)) picked.push(r);\n  return picked.map(({ item, reason }) => ({ item, reason }));\n}\n\n/** One or two short videos, favouring his topics. */\nexport function quickVideos(p: Personal, library: ContentItem[], count = 2): ContentItem[] {\n  return library\n    .filter((c) => c.kind === \"video\")\n    .sort((a, b) => Number(p.interests.includes(b.topic)) - Number(p.interests.includes(a.topic)) || Number(!!p.history[a.id]) - Number(!!p.history[b.id]) || b.priority - a.priority)\n    .slice(0, count);\n}\n\n/** One question men often ask, changing daily, favouring his topics and ones he hasn't read. */\nexport function questionToday(p: Personal, library: ContentItem[], day = dayNumber()): ContentItem | null {\n  const all = library.filter((c) => c.kind === \"expert\" && c.question);\n  if (!all.length) return null;\n  const unread = all.filter((c) => !p.history[c.id]);\n  const mine = unread.filter((c) => p.interests.includes(c.topic));\n  const pool = mine.length ? mine : unread.length ? unread : all;\n  return [...pool].sort((a, b) => a.id.localeCompare(b.id))[day % pool.length];\n}\n\n/** Every topic and format with how many items it has — for \"Explore all topics\". */\nexport function topicTiles(library: ContentItem[]) {\n  return SECTIONS.map((s) => ({ ...s, count: sectionAll(s.id, library).length }));\n}\n",
  "src/lib/content/types.ts": "// Shape of every piece of educational content in Men's Social.\n// Today: sample items in library.ts. Later: rows in the Content Studio (admin) / database.\n\nexport type TopicId = \"erection\" | \"ejaculation\" | \"libido\" | \"fertility\" | \"confidence\" | \"intimacy\" | \"wellbeing\";\n\nexport type ContentKind = \"guide\" | \"article\" | \"video\" | \"quiz\" | \"tool\" | \"expert\";\n\nexport type ToolId = \"pelvic-floor\" | \"doctor-check\";\n\nexport interface QuizQuestion {\n  q: string;\n  options: string[];\n  answer: number; // index of the correct option\n  explain: string;\n}\n\nexport interface ContentItem {\n  id: string;\n  kind: ContentKind;\n  topic: TopicId;\n  title: string;\n  /** What he gains from it, in one or two short sentences. */\n  summary: string;\n  minutes: number;\n  /** Editorial priority 0–100: higher is more likely to be featured. */\n  priority: number;\n  tags: string[];\n  /** Paragraphs. A paragraph starting with \"## \" is shown as a heading. */\n  body?: string[];\n  keyPoints?: string[];\n  question?: string; // expert answers\n  quiz?: QuizQuestion[];\n  tool?: ToolId;\n  /** Who wrote it and its review state — always shown to the reader. */\n  source: string;\n  review: \"draft\" | \"reviewed\";\n  /** true = development sample, to be replaced by real content from the Content Studio. */\n  fixture: boolean;\n  /** Shown as a daily lesson on the Man tab too. */\n  inManFeed?: boolean;\n  points?: number;\n  cover: { tone: \"forest\" | \"night\" | \"mint\" | \"sand\" | \"clay\"; motif: \"rings\" | \"waves\" | \"arc\" | \"grid\" | \"dots\" };\n  /** Kiswahili version of the body (same \"## \" heading rule). */\n  bodySw?: string[];\n  titleSw?: string;\n  /** Where the content was adapted from, e.g. a Kayani Herbs Instagram post. */\n  origin?: { platform: \"instagram\"; url: string; postedAt: string; format: \"reel\" | \"post\" | \"carousel\" };\n  /** Uploaded cover photo (Content Studio). When set, it replaces the drawn cover. */\n  coverImageUrl?: string;\n  /** Content Studio fields */\n  status?: ContentStatus;\n  updatedAt?: string;\n  /** true = shipped with the app (catalog files), false/undefined = from the database */\n  builtIn?: boolean;\n}\n\nexport type ContentStatus = \"draft\" | \"published\" | \"archived\";\n\nexport interface Topic {\n  id: TopicId;\n  title: string;\n  short: string;\n}\n",
  "src/lib/feed/catalog.ts": "// Starter content for the Home feed.\n// This is CONTENT, not user data: it moves into the Content Studio (admin) later,\n// where Daud can add, edit and schedule it. Point values are configurable there too.\n\nimport { LIBRARY } from \"../content/library\";\nimport type { ContentItem } from \"../content/types\";\n\nexport type Slot = \"morning\" | \"afternoon\" | \"evening\";\n\n/** \"tracker\" activities complete themselves when the matching record exists. */\nexport type Tracker = \"checkin\" | \"sleep\" | \"water\";\n\nexport interface Activity {\n  id: string;\n  title: string;\n  discreetTitle: string; // shown when discreet mode is on\n  detail: string;\n  points: number;\n  slot: Slot | \"any\";\n  tracker?: Tracker;\n  why: string; // shown under \"Why am I seeing this?\"\n}\n\nexport const ACTIVITIES: Activity[] = [\n  {\n    id: \"checkin\",\n    title: \"Energy and mood check-in\",\n    discreetTitle: \"Daily check-in\",\n    detail: \"Two taps. Helps you notice patterns over time.\",\n    points: 10,\n    slot: \"morning\",\n    tracker: \"checkin\",\n    why: \"A daily check-in is how you and the app learn what affects your energy.\",\n  },\n  {\n    id: \"sleep\",\n    title: \"Log last night's sleep\",\n    discreetTitle: \"Log last night\",\n    detail: \"Bedtime, wake-up time and how well you slept.\",\n    points: 10,\n    slot: \"morning\",\n    tracker: \"sleep\",\n    why: \"Sleep affects energy, mood and overall wellbeing, so it's worth tracking.\",\n  },\n  {\n    id: \"water\",\n    title: \"Reach your water goal\",\n    discreetTitle: \"Water goal\",\n    detail: \"Log glasses and bottles as you drink through the day.\",\n    points: 15,\n    slot: \"any\",\n    tracker: \"water\",\n    why: \"Staying hydrated supports energy and digestion. Your goal is set by you.\",\n  },\n  {\n    id: \"walk\",\n    title: \"Take a 20-minute walk\",\n    discreetTitle: \"20-minute walk\",\n    detail: \"Any pace that feels comfortable. Outside if you can.\",\n    points: 15,\n    slot: \"afternoon\",\n    why: \"Regular walking supports circulation, mood and sleep.\",\n  },\n  {\n    id: \"breathe\",\n    title: \"5 minutes of slow breathing\",\n    discreetTitle: \"5-minute breathing\",\n    detail: \"Breathe in for 4 seconds, out for 6. Repeat for 5 minutes.\",\n    points: 10,\n    slot: \"evening\",\n    why: \"Slow breathing is a simple way to calm stress at the end of the day.\",\n  },\n  {\n    id: \"screens-off\",\n    title: \"Screens off 30 minutes before bed\",\n    discreetTitle: \"Screens off before bed\",\n    detail: \"Put the phone away and let your mind slow down.\",\n    points: 10,\n    slot: \"evening\",\n    why: \"Less screen time before bed can make it easier to fall asleep.\",\n  },\n];\n\nexport interface Lesson {\n  id: string;\n  title: string;\n  topic: string;\n  minutes: number;\n  summary: string;\n  body: string[]; // paragraphs\n  points: number;\n}\n\n// Daily lessons on the Man tab come from the shared content library (same items as in Discover).\nconst TOPIC_LABEL: Record<string, string> = {\n  erection: \"Erections\",\n  ejaculation: \"Lasting longer\",\n  libido: \"Desire\",\n  fertility: \"Fertility\",\n  confidence: \"Confidence\",\n  intimacy: \"Intimacy\",\n  wellbeing: \"Lifestyle\",\n};\n\n/** Daily lessons for the Man tab: any content marked \"show on Man tab\" (built-in or published in the Studio). */\nexport function lessonsFrom(items: ContentItem[]): Lesson[] {\n  return items\n    .filter((c) => c.inManFeed)\n    .map((c) => ({\n      id: c.id,\n      title: c.title,\n      topic: TOPIC_LABEL[c.topic] ?? c.topic,\n      minutes: c.minutes,\n      summary: c.summary,\n      body: c.body ?? [],\n      points: c.points ?? 10,\n    }));\n}\n\nexport const LESSONS: Lesson[] = lessonsFrom(LIBRARY);\n\nexport const TIPS: string[] = [\n  \"Drink a glass of water before your morning tea.\",\n  \"A short walk after a meal can help you feel lighter.\",\n  \"Go to bed at the same time tonight as last night.\",\n  \"Small steps every day beat big plans you don't keep.\",\n  \"Put your phone in another room when you sleep.\",\n  \"Take the stairs today, even for one floor.\",\n  \"Missed a day? Just start again today. No pressure.\",\n];\n",
  "src/lib/social/community.ts": "// Community rules and helpers. Pure functions — easy to test, reused when the server arrives.\n\nimport type { TopicId } from \"../content/types\";\n\nexport type CommunityTopic = TopicId | \"general\";\n\nexport const COMMUNITY_TOPICS: { id: CommunityTopic; label: string }[] = [\n  { id: \"general\", label: \"General\" },\n  { id: \"erection\", label: \"Erections\" },\n  { id: \"ejaculation\", label: \"Lasting longer\" },\n  { id: \"libido\", label: \"Desire\" },\n  { id: \"fertility\", label: \"Fertility\" },\n  { id: \"confidence\", label: \"Confidence\" },\n  { id: \"intimacy\", label: \"Relationships\" },\n  { id: \"wellbeing\", label: \"Body and mind\" },\n];\n\nexport type ReactionKind = \"support\" | \"helpful\" | \"same\";\n\nexport const REACTIONS: { kind: ReactionKind; label: string; emoji: string }[] = [\n  { kind: \"support\", label: \"Support\", emoji: \"🤝\" },\n  { kind: \"helpful\", label: \"Helpful\", emoji: \"💡\" },\n  { kind: \"same\", label: \"Same here\", emoji: \"🙋\" },\n];\n\nexport interface Author {\n  name: string; // nickname, or \"Anonymous member\"\n  anonymous: boolean;\n}\n\nexport interface Post {\n  id: string;\n  topic: CommunityTopic;\n  title: string;\n  body: string;\n  author: Author;\n  createdAt: string;\n  wantsExpert?: boolean;\n  fixture?: boolean; // sample post for development\n  mine?: boolean;\n  baseReactions?: Partial<Record<ReactionKind, number>>;\n}\n\nexport interface Reply {\n  id: string;\n  postId: string;\n  body: string;\n  author: Author;\n  createdAt: string;\n  fixture?: boolean;\n  mine?: boolean;\n  baseReactions?: Partial<Record<ReactionKind, number>>;\n}\n\nexport const REPORT_REASONS = [\n  \"Selling or advertising\",\n  \"Medical misinformation\",\n  \"Harassment or disrespect\",\n  \"Sharing someone's private information\",\n  \"Sexual or explicit content\",\n  \"Something else\",\n] as const;\n\nconst PHONE = /(\\+?\\d[\\d\\s-]{7,}\\d)/;\nconst LINK = /(https?:\\/\\/|www\\.|\\.com\\b|\\.co\\.tz\\b|wa\\.me|t\\.me\\/)/i;\nconst CONTACT = /\\b(whats\\s?app|call me|inbox me|dm me|nipigie|nitumie|namba yangu|my number)\\b/i;\nconst SELLING = /\\b(tsh|tzs|shilingi|price|bei|order now|buy now|nunua|for sale|inauzwa|delivery|discount)\\b/i;\n\nexport const LIMITS = { titleMin: 8, titleMax: 120, bodyMax: 1000, replyMin: 2, replyMax: 600 };\n\n/** Returns a friendly error, or null if the post can be published. */\nexport function checkPost(title: string, body: string): string | null {\n  const t = title.trim();\n  const b = body.trim();\n  if (t.length < LIMITS.titleMin) return \"Write your question in a few more words.\";\n  if (t.length > LIMITS.titleMax) return `Keep the question under ${LIMITS.titleMax} characters. Add details below.`;\n  if (b.length > LIMITS.bodyMax) return `Details can be up to ${LIMITS.bodyMax} characters.`;\n  return checkText(`${t} ${b}`);\n}\n\nexport function checkReply(body: string): string | null {\n  const b = body.trim();\n  if (b.length < LIMITS.replyMin) return \"Write a reply first.\";\n  if (b.length > LIMITS.replyMax) return `Replies can be up to ${LIMITS.replyMax} characters.`;\n  return checkText(b);\n}\n\n/** Shared safety checks: protects members from scams and protects privacy. */\nexport function checkText(text: string): string | null {\n  if (PHONE.test(text)) return \"Phone numbers can't be shared here, to protect everyone's privacy.\";\n  if (LINK.test(text)) return \"Links can't be shared in the community.\";\n  if (CONTACT.test(text)) return \"Please keep conversations in the community — no private contact requests.\";\n  if (SELLING.test(text)) return \"Selling and prices aren't allowed in the community.\";\n  return null;\n}\n\nexport function reactionCount(\n  base: Partial<Record<ReactionKind, number>> | undefined,\n  mine: ReactionKind[] | undefined,\n  kind: ReactionKind,\n): number {\n  return (base?.[kind] ?? 0) + (mine?.includes(kind) ? 1 : 0);\n}\n\nexport function toggleReaction(mine: ReactionKind[] | undefined, kind: ReactionKind): ReactionKind[] {\n  const list = mine ?? [];\n  return list.includes(kind) ? list.filter((k) => k !== kind) : [...list, kind];\n}\n\n/** \"Most active\" = replies count most, then reactions. */\nexport function activityScore(replies: number, reactions: number): number {\n  return replies * 3 + reactions;\n}\n\nexport function timeAgo(iso: string, now: Date = new Date()): string {\n  const s = Math.max(0, (now.getTime() - new Date(iso).getTime()) / 1000);\n  if (s < 60) return \"just now\";\n  if (s < 3600) return `${Math.floor(s / 60)}m ago`;\n  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;\n  if (s < 7 * 86400) return `${Math.floor(s / 86400)}d ago`;\n  return new Date(iso).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\" });\n}\n\nexport function topicLabel(id: CommunityTopic): string {\n  return COMMUNITY_TOPICS.find((t) => t.id === id)?.label ?? \"General\";\n}\n",
  "src/lib/social/store.ts": "\"use client\";\n\n// Saves Social data: bookmarks, chosen topics, his posts and replies, reactions and reports.\n// NOW: on this phone only (localStorage). LATER: the server, so other men can see his posts.\n\nimport { useSyncExternalStore } from \"react\";\nimport type { TopicId } from \"../content/types\";\nimport { toggleReaction, type CommunityTopic, type Post, type ReactionKind, type Reply } from \"./community\";\n\nexport interface SocialDB {\n  bookmarks: Record<string, string>; // contentId → saved at\n  interests: TopicId[];\n  nickname: string;\n  posts: Post[]; // his own posts\n  replies: Reply[]; // his own replies\n  reactions: Record<string, ReactionKind[]>; // postId/replyId → his reactions\n  reports: Record<string, { reason: string; at: string }>; // reported items (hidden for him, queued for moderators)\n  /** Guides and answers he opened (contentId → last opened). Used to recommend what he hasn't read yet. */\n  history: Record<string, string>;\n}\nexport type SocialState = SocialDB & { ready: boolean };\n\nconst KEY = \"ms_social_v1\";\nconst EMPTY: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {}, history: {} };\nconst SERVER_STATE: SocialState = { ...EMPTY, ready: false };\nlet cache: SocialState | null = null;\nconst listeners = new Set<() => void>();\n/** Told only about HIS changes (not about data arriving from his account), so they can be saved to it. */\nconst changeListeners = new Set<() => void>();\n\nconst obj = <T,>(v: unknown, fallback: T): T => (v && typeof v === \"object\" ? (v as T) : fallback);\n\nfunction load(): SocialState {\n  if (cache) return cache;\n  let db = EMPTY;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const p = JSON.parse(raw) as Partial<SocialDB>;\n      db = {\n        bookmarks: obj(p.bookmarks, {}),\n        interests: Array.isArray(p.interests) ? p.interests : [],\n        nickname: typeof p.nickname === \"string\" ? p.nickname : \"\",\n        posts: Array.isArray(p.posts) ? p.posts : [],\n        replies: Array.isArray(p.replies) ? p.replies : [],\n        reactions: obj(p.reactions, {}),\n        reports: obj(p.reports, {}),\n        history: obj(p.history, {}),\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: SocialDB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // keep working in memory\n  }\n  listeners.forEach((l) => l());\n  changeListeners.forEach((l) => l());\n}\n\nconst id = () =>\n  typeof crypto !== \"undefined\" && \"randomUUID\" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;\n\nexport function useSocial(): SocialState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\nconst HISTORY_LIMIT = 150;\n\nexport const socialStore = {\n  /** He opened a guide, video or answer. Keeps the most recent ones only. */\n  recordOpen(contentId: string) {\n    const db = load();\n    const history = { ...db.history, [contentId]: new Date().toISOString() };\n    const keep = Object.entries(history)\n      .sort((a, b) => b[1].localeCompare(a[1]))\n      .slice(0, HISTORY_LIMIT);\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n    const { ready, ...rest } = db;\n    save({ ...rest, history: Object.fromEntries(keep) });\n  },\n\n  toggleBookmark(contentId: string): boolean {\n    const db = load();\n    const next = { ...db.bookmarks };\n    const saved = !next[contentId];\n    if (saved) next[contentId] = new Date().toISOString();\n    else delete next[contentId];\n    save({ ...db, bookmarks: next });\n    return saved;\n  },\n\n  setInterests(interests: TopicId[]) {\n    save({ ...load(), interests });\n  },\n\n  setNickname(nickname: string) {\n    save({ ...load(), nickname: nickname.trim().slice(0, 24) });\n  },\n\n  addPost(input: { topic: CommunityTopic; title: string; body: string; anonymous: boolean; wantsExpert: boolean }): Post {\n    const db = load();\n    const post: Post = {\n      id: id(),\n      topic: input.topic,\n      title: input.title.trim(),\n      body: input.body.trim(),\n      author: input.anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      wantsExpert: input.wantsExpert,\n      mine: true,\n    };\n    save({ ...db, posts: [post, ...db.posts] });\n    return post;\n  },\n\n  deletePost(postId: string) {\n    const db = load();\n    save({ ...db, posts: db.posts.filter((p) => p.id !== postId), replies: db.replies.filter((r) => r.postId !== postId) });\n  },\n\n  addReply(postId: string, body: string, anonymous: boolean): Reply {\n    const db = load();\n    const reply: Reply = {\n      id: id(),\n      postId,\n      body: body.trim(),\n      author: anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      mine: true,\n    };\n    save({ ...db, replies: [...db.replies, reply] });\n    return reply;\n  },\n\n  deleteReply(replyId: string) {\n    const db = load();\n    save({ ...db, replies: db.replies.filter((r) => r.id !== replyId) });\n  },\n\n  react(targetId: string, kind: ReactionKind) {\n    const db = load();\n    save({ ...db, reactions: { ...db.reactions, [targetId]: toggleReaction(db.reactions[targetId], kind) } });\n  },\n\n  report(targetId: string, reason: string) {\n    const db = load();\n    save({ ...db, reports: { ...db.reports, [targetId]: { reason, at: new Date().toISOString() } } });\n  },\n\n  undoReport(targetId: string) {\n    const db = load();\n    const reports = { ...db.reports };\n    delete reports[targetId];\n    save({ ...db, reports });\n  },\n};\n\n/** Used by account sync: read, replace or clear this phone's copy. */\nexport const socialSync = {\n  get(): SocialDB {\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n    const { ready, ...db } = load();\n    return db;\n  },\n  /** Data from his account: saved on the phone and shown, but not sent back again. */\n  replace(db: SocialDB) {\n    try {\n      localStorage.setItem(KEY, JSON.stringify(db));\n    } catch {}\n    cache = null;\n    load();\n    listeners.forEach((l) => l());\n  },\n  clear() {\n    try {\n      localStorage.removeItem(KEY);\n    } catch {}\n    cache = null;\n    listeners.forEach((l) => l());\n  },\n  onChange(cb: () => void) {\n    changeListeners.add(cb);\n    return () => {\n      changeListeners.delete(cb);\n    };\n  },\n};\n",
  "src/lib/supabase/migration.test.ts": "// Runs the real migration SQL in a real Postgres (PGlite) with small stand-ins for\n// Supabase's auth and storage schemas, then checks the security rules.\nimport { readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { PGlite } from \"@electric-sql/pglite\";\nimport { beforeAll, describe, expect, it } from \"vitest\";\n\nconst ADMIN = \"11111111-1111-1111-1111-111111111111\";\nconst USER = \"22222222-2222-2222-2222-222222222222\";\n\nconst SUPABASE_STANDINS = `\n  create schema auth;\n  create table auth.users (id uuid primary key);\n  create function auth.uid() returns uuid language sql stable as\n    $$ select nullif(current_setting('test.uid', true), '')::uuid $$;\n  create schema storage;\n  create table storage.buckets (id text primary key, name text, public boolean);\n  create table storage.objects (id serial primary key, bucket_id text, name text);\n  alter table storage.objects enable row level security;\n  create role anon; create role authenticated;\n`;\n\nconst GRANTS = `\n  grant usage on schema public, auth, storage to anon, authenticated;\n  grant select on all tables in schema public to anon, authenticated;\n  grant insert, update, delete on public.content_items to authenticated;\n  grant select, insert, update, delete on storage.objects to authenticated;\n  grant select on storage.objects to anon;\n  grant usage, select on all sequences in schema storage to authenticated;\n  grant execute on all functions in schema public, auth to anon, authenticated;\n`;\n\nlet db: PGlite;\n\nasync function as(uid: string | null, role: \"anon\" | \"authenticated\", sql: string, params: unknown[] = []) {\n  await db.exec(`reset role; select set_config('test.uid', '${uid ?? \"\"}', false); set role ${role};`);\n  try {\n    return await db.query(sql, params);\n  } finally {\n    await db.exec(\"reset role;\");\n  }\n}\n\nconst insertSql = `insert into public.content_items (id, kind, topic, title, status)\n  values ($1, 'article', 'erection', 'A test article', $2)`;\n\nbeforeAll(async () => {\n  db = new PGlite();\n  await db.exec(SUPABASE_STANDINS);\n  const migration = readFileSync(join(process.cwd(), \"supabase/migrations/0001_content_studio.sql\"), \"utf8\");\n  await db.exec(migration);\n  await db.exec(migration); // must be safe to run twice\n  const fertility = readFileSync(join(process.cwd(), \"supabase/migrations/0003_fertility_topic.sql\"), \"utf8\");\n  await db.exec(fertility);\n  await db.exec(fertility);\n  await db.exec(GRANTS);\n  await db.query(\"insert into auth.users (id) values ($1), ($2)\", [ADMIN, USER]);\n  await db.query(\"insert into public.admins (user_id, role) values ($1, 'owner')\", [ADMIN]);\n}, 30_000);\n\ndescribe(\"content security rules\", () => {\n  it(\"an admin can create drafts and published items\", async () => {\n    await as(ADMIN, \"authenticated\", insertSql, [\"draft-one\", \"draft\"]);\n    await as(ADMIN, \"authenticated\", insertSql, [\"live-one\", \"published\"]);\n    const all = await as(ADMIN, \"authenticated\", \"select id from public.content_items order by id\");\n    expect(all.rows.map((r) => (r as { id: string }).id)).toEqual([\"draft-one\", \"live-one\"]);\n  });\n\n  it(\"the public (not signed in) sees only published content\", async () => {\n    const r = await as(null, \"anon\", \"select id from public.content_items\");\n    expect(r.rows.map((x) => (x as { id: string }).id)).toEqual([\"live-one\"]);\n  });\n\n  it(\"a signed-in man who is not an admin also sees only published content\", async () => {\n    const r = await as(USER, \"authenticated\", \"select id from public.content_items\");\n    expect(r.rows.map((x) => (x as { id: string }).id)).toEqual([\"live-one\"]);\n  });\n\n  it(\"a non-admin cannot create, change or delete content\", async () => {\n    await expect(as(USER, \"authenticated\", insertSql, [\"sneaky\", \"published\"])).rejects.toThrow(/row-level security/);\n    const upd = await as(USER, \"authenticated\", \"update public.content_items set title = 'hacked' where id = 'live-one' returning id\");\n    expect(upd.rows).toHaveLength(0);\n    const del = await as(USER, \"authenticated\", \"delete from public.content_items where id = 'live-one' returning id\");\n    expect(del.rows).toHaveLength(0);\n  });\n\n  it(\"publishing sets published_at and records who changed it\", async () => {\n    await as(ADMIN, \"authenticated\", \"update public.content_items set status = 'published' where id = 'draft-one'\");\n    const r = await db.query<{ published_at: string | null; updated_by: string; created_by: string }>(\n      \"select published_at, updated_by, created_by from public.content_items where id = 'draft-one'\",\n    );\n    expect(r.rows[0].published_at).not.toBeNull();\n    expect(r.rows[0].updated_by).toBe(ADMIN);\n    expect(r.rows[0].created_by).toBe(ADMIN);\n  });\n\n  it(\"keeps an audit log that only admins can read\", async () => {\n    const admin = await as(ADMIN, \"authenticated\", \"select action, status_after from public.content_audit where content_id = 'draft-one' order by id\");\n    expect(admin.rows).toEqual([\n      { action: \"insert\", status_after: \"draft\" },\n      { action: \"update\", status_after: \"published\" },\n    ]);\n    const user = await as(USER, \"authenticated\", \"select * from public.content_audit\");\n    expect(user.rows).toHaveLength(0);\n  });\n\n  it(\"accepts the Fertility topic (migration 0003)\", async () => {\n    await as(ADMIN, \"authenticated\", \"insert into public.content_items (id, kind, topic, title) values ('sperm-health', 'article', 'fertility', 'Sperm health')\");\n    const r = await db.query<{ topic: string }>(\"select topic from public.content_items where id = 'sperm-health'\");\n    expect(r.rows[0].topic).toBe(\"fertility\");\n  });\n\n  it(\"rejects bad values (unknown topic, bad id)\", async () => {\n    await expect(\n      as(ADMIN, \"authenticated\", \"insert into public.content_items (id, kind, topic, title) values ('ok-id', 'article', 'football', 'Title')\"),\n    ).rejects.toThrow();\n    await expect(\n      as(ADMIN, \"authenticated\", \"insert into public.content_items (id, kind, topic, title) values ('Bad ID!', 'article', 'erection', 'Title')\"),\n    ).rejects.toThrow();\n  });\n\n  it(\"only admins can upload images\", async () => {\n    await as(ADMIN, \"authenticated\", \"insert into storage.objects (bucket_id, name) values ('content-images', 'a.jpg')\");\n    await expect(\n      as(USER, \"authenticated\", \"insert into storage.objects (bucket_id, name) values ('content-images', 'b.jpg')\"),\n    ).rejects.toThrow(/row-level security/);\n    const pub = await as(null, \"anon\", \"select name from storage.objects\");\n    expect(pub.rows).toEqual([{ name: \"a.jpg\" }]);\n  });\n});\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files. Next: npm test, then npx next dev --turbopack, then open http://localhost:3000");
